// CERO 01 :: Normalize instrument JSON -> flat, administrable item bank.
//
// Both source branches are read directly by node name rather than through Merge Sources.
// The merge was silently dropping the instruments branch, which produced an empty item
// bank with no error. Reading the nodes explicitly removes that whole failure mode.

let instrumentsRaw = {};
try { instrumentsRaw = $('Extract: Instruments').first().json || {}; } catch (e) { instrumentsRaw = {}; }

let qaRows = [];
try { qaRows = ($('Aggregate QA Rows').first().json || {}).data || []; } catch (e) { qaRows = []; }

// The extract node's destination key has moved around; accept every plausible shape.
function findInstruments(o) {
  if (!o || typeof o !== 'object') return null;
  if (Array.isArray(o.cognitive_assessments)) return o.cognitive_assessments;
  if (Array.isArray(o.instruments)) return o.instruments;
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (v && typeof v === 'object') {
      const found = findInstruments(v);
      if (found) return found;
    }
  }
  return null;
}

const instruments = findInstruments(instrumentsRaw) || [];

if (!instruments.length) {
  throw new Error('No instruments found. Extract: Instruments returned keys: ' +
    Object.keys(instrumentsRaw).join(', ') + '. Expected cognitive_assessments[] somewhere inside.');
}

const toInt = (v) => {
  if (v === null || v === undefined) return 0;
  const n = parseInt(String(v), 10);
  return Number.isFinite(n) ? n : 0;
};
const isTrue = (v) => v === true || String(v).toLowerCase() === 'true';

const AGENT_MAP = {
  'orientation to time': 'orientation_agent',
  'orientation to place': 'orientation_agent',
  'personal orientation': 'orientation_agent',
  'temporal orientation': 'orientation_agent',
  'place orientation': 'orientation_agent',
  'orientation': 'orientation_agent',
  'registration': 'memory_recall_agent',
  'recall': 'memory_recall_agent',
  'memory': 'memory_recall_agent',
  'delayed recall': 'memory_recall_agent',
  'immediate recall (cued)': 'memory_recall_agent',
  'delayed recall (cued)': 'memory_recall_agent',
  'attention and calculation': 'attention_calc_agent',
  'attention': 'attention_calc_agent',
  'counting': 'attention_calc_agent',
  'spelling': 'attention_calc_agent',
  'language': 'language_naming_agent',
  'repetition': 'language_naming_agent',
  'naming': 'language_naming_agent',
  'naming (body parts)': 'language_naming_agent',
  'verbal fluency (animals)': 'language_naming_agent',
  'sentence repetition': 'language_naming_agent',
  'repetition (complex phrase)': 'language_naming_agent',
  'reading comprehension': 'language_naming_agent',
  'complex commands': 'visuospatial_exec_agent',
  'visuospatial / executive': 'visuospatial_exec_agent',
  'visuoconstructional skills (pentagon copying)': 'visuospatial_exec_agent',
  '3-stage command': 'visuospatial_exec_agent',
  'writing': 'visuospatial_exec_agent',
  'abstraction': 'abstraction_agent',
  'abstraction / similarities': 'abstraction_agent',
  'special problems': 'excluded'
};

function responseMode(text) {
  const t = (text || '').toLowerCase();
  if (/\b(draw|copy this|copy the|copy that|clock|cube|pentagon|trail making|drawing)\b/.test(t)) return 'drawing';
  if (/\b(tap|fold|put it on the floor|take the paper|take this paper|hand it back|point to)\b/.test(t)) return 'motor_observed';
  if (/close your eyes|read this and do what it says|please do this/.test(t)) return 'read_and_act';
  if (/as many (words|of those|animals)|one minute|30 seconds|60 seconds|four legs/.test(t)) return 'timed_verbal';
  if (/name of this animal|what do you call this part|and this part/.test(t)) return 'visual_stimulus';
  if (/show (the )?patient|point to each figure|stimuli card/.test(t)) return 'visual_stimulus';
  return 'verbal';
}

function assetId(instrumentId, domain, label) {
  const t = ((domain || '') + ' ' + (label || '')).toLowerCase();
  if (instrumentId.startsWith('mmse') && /copy|pentagon/.test(t)) return 'mmse_pentagons';
  if (instrumentId.startsWith('mmse') && /reading/.test(t)) return 'mmse_close_your_eyes_card';
  if (instrumentId === 'moca' && /trail/.test(t)) return 'moca_trail_making';
  if (instrumentId === 'moca' && /cube/.test(t)) return 'moca_cube';
  if (instrumentId === 'moca' && /clock/.test(t)) return 'moca_clock_blank';
  if (instrumentId === 'moca' && /naming/.test(t)) return 'moca_naming_set';
  if (instrumentId === 'moca' && /vigilance|letter a/.test(t)) return 'moca_letter_list';
  return null;
}

// The three source files name the recall stimulus three different ways: MoCA uses
// word_list, MMSE uses sample_words, the modified MMSE uses words. Recall domains
// carry no list of their own by design, because their instructions reference the list
// the Registration domain already presented, so the resolved list is carried forward
// within each instrument. Looking only for `word_list` is why MMSE Registration and
// Recall were both marked stimulus_list_absent_from_source while the words sat in the
// file under `sample_words`.
function domWordList(dom) {
  for (const c of [dom.word_list, dom.sample_words, dom.words]) {
    if (Array.isArray(c) && c.length) return c;
  }
  return null;
}
let carriedList = null;

const bank = [];
const domainIndex = [];
let seq = 0;

function push(inst, dom, o) {
  const label = o.label || o.task || o.question || '';
  const promptText = (o.question || o.prompt || '').trim();
  const mode = responseMode([o.task, o.question, o.instructions, dom.domain].join(' '));
  seq += 1;

  const refText = [promptText, o.scoring_note, dom.scoring_note, o.instructions, dom.instructions].join(' ');
  const needsList = /three (named )?(objects|words|things)|list of words|word list|the three|unrelated objects/i.test(refText);
  const resolvedList = (o.stimulus && o.stimulus.word_list)
    || domWordList(dom)
    || carriedList;
  const hasList = Array.isArray(resolvedList) && resolvedList.length > 0;
  const stimulusMissing = needsList && !hasList;

  // An item that needs the words must actually carry them, or the assessor has the
  // item wording but nothing to present or score against.
  const stimulus = o.stimulus
    || (needsList && hasList
      ? { word_list: resolvedList, trials: toInt(dom.trials) || 6, cuing: dom.cuing_protocol || null }
      : null);

  bank.push({
    item_uid: inst.id + '::' + seq,
    instrument_id: inst.id,
    instrument_name: inst.name,
    domain: dom.domain,
    domain_order: dom.__order,
    agent_id: AGENT_MAP[(dom.domain || '').toLowerCase()] || 'unmapped',
    item_order: seq,
    label: label,
    prompt_text: promptText,
    administration_instructions: o.instructions || dom.instructions || '',
    max_points: toInt(o.max_points !== undefined ? o.max_points : o.points),
    scoring_note: o.scoring_note || dom.scoring_note || '',
    scoring_levels: o.scoring_levels || null,
    expected_responses: o.expected_responses || o.expected_response || null,
    stimulus: stimulus,
    response_mode: mode,
    asset_id: o.asset_id || assetId(inst.id, dom.domain, label),
    is_alternative: isTrue(o.is_alternative),
    alternative_for: o.alternative_for || null,
    encode_only: dom.max_points === 0,
    stimulus_missing: stimulusMissing,
    administrable: !stimulusMissing,
    blocking_reason: stimulusMissing ? 'stimulus_list_absent_from_source' : null
  });
}

for (const inst of instruments) {
  const domains = inst.domains || [];
  carriedList = null;
  domains.forEach((dom, di) => {
    dom.__order = di;
    const ownList = domWordList(dom);
    if (ownList) carriedList = ownList;
    const before = bank.length;

    const units = dom.items || dom.tasks || [];
    for (const u of units) {
      if (Array.isArray(u.objects_shown) && u.objects_shown.length) {
        // Split a multi-object naming item into one item per object. Mirrors the
        // existing dom.animals_shown handling for MoCA naming, and matches plan 4.2,
        // which addresses stimuli one per item ("naming-item-2"). The MMSE shows the
        // watch and the pencil separately and scores 1 point each, so a single 2-point
        // item with one shared prompt cannot be administered or scored correctly.
        u.objects_shown.forEach((ob, i) => {
          const objName = typeof ob === 'string' ? ob : (ob.object || ob.name || '');
          const objAsset = typeof ob === 'string' ? null : (ob.asset_id || null);
          push(inst, dom, {
            label: (u.task || dom.domain) + '-item-' + (i + 1),
            question: u.question,
            instructions: u.instructions,
            max_points: 1,
            scoring_note: 'Accept ' + objName + '. ' + (u.scoring_note || ''),
            expected_responses: [objName],
            asset_id: objAsset,
            stimulus: { expected: objName, asset_index: i + 1 }
          });
        });
      } else if (Array.isArray(u.scoring_sub_items) && u.scoring_sub_items.length) {
        for (const s of u.scoring_sub_items) {
          push(inst, dom, {
            label: (u.task || '') + ' - ' + s.label,
            question: u.question,
            instructions: u.instructions,
            max_points: s.points,
            scoring_note: u.scoring_note
          });
        }
      } else {
        push(inst, dom, u);
      }
    }

    if (Array.isArray(dom.sub_items)) {
      for (const s of dom.sub_items) {
        let pts = 0;
        if (s.points !== undefined) pts = toInt(s.points);
        else if (s.points_if_correct !== undefined) pts = toInt(s.points_if_correct);
        else if (Array.isArray(s.scoring_levels)) pts = Math.max(...s.scoring_levels.map(x => toInt(x.score)));
        const component = s.phrase_component || s.word || s.component || null;
        push(inst, dom, {
          label: s.label + (component ? ' (' + component + ')' : ''),
          question: s.question || dom.question,
          instructions: dom.instructions,
          max_points: pts,
          scoring_levels: s.scoring_levels || null,
          scoring_note: component
            ? 'Scored component: "' + component + '". ' + (dom.scoring_note || '')
            : dom.scoring_note,
          stimulus: component ? { component: component } : null
        });
      }
    }

    if (Array.isArray(dom.word_list) && !units.length && !dom.sub_items) {
      push(inst, dom, {
        label: dom.domain,
        question: dom.question_trial_1 || dom.question,
        instructions: dom.instructions,
        max_points: dom.max_points,
        scoring_note: dom.scoring_note,
        stimulus: { word_list: dom.word_list, trials: dom.trials || 1, cuing: dom.cuing_protocol || null }
      });
    }

    if (Array.isArray(dom.test_pairs)) {
      for (const p of dom.test_pairs) {
        push(inst, dom, {
          label: 'similarity: ' + (p.items || []).join(' / '),
          question: dom.question || 'In what way are ' + (p.items || []).join(' and ') + ' alike?',
          instructions: dom.instructions,
          max_points: 1,
          scoring_note: p.scoring_note || dom.scoring_note,
          stimulus: { pair: p.items, practice_pair: dom.practice_pair || null }
        });
      }
    }

    if (Array.isArray(dom.animals_shown)) {
      dom.animals_shown.forEach((a, i) => {
        push(inst, dom, {
          label: 'naming-item-' + (i + 1),
          question: dom.question,
          instructions: dom.instructions,
          max_points: 1,
          scoring_note: 'Accept ' + a,
          stimulus: { expected: a, asset_index: i + 1 }
        });
      });
    }

    if (bank.length === before && (dom.question || dom.instructions)) {
      push(inst, dom, {
        label: dom.domain,
        question: dom.question,
        instructions: dom.instructions,
        max_points: dom.max_points,
        scoring_note: dom.scoring_note
      });
    }

    const produced = bank.slice(before);
    domainIndex.push({
      instrument_id: inst.id,
      domain: dom.domain,
      domain_order: di,
      agent_id: AGENT_MAP[(dom.domain || '').toLowerCase()] || 'unmapped',
      declared_max_points: toInt(dom.max_points),
      derived_max_points: produced.filter(x => !x.is_alternative).reduce((a, b) => a + b.max_points, 0),
      item_count: produced.length
    });
  });
}

const instrumentMeta = instruments.map(i => ({
  id: i.id,
  name: i.name,
  abbreviation: i.abbreviation,
  version: i.version,
  source: i.source,
  declared_total_points: toInt(i.total_points),
  administration_time_minutes: i.administration_time_minutes,
  education_adjustment: i.education_adjustment || null,
  scoring_interpretation: i.scoring_interpretation || null,
  memory_index_score: i.memory_index_score || null
}));

return [{ json: {
  qa_rows: qaRows,
  instrument_meta: instrumentMeta,
  domain_index: domainIndex,
  item_bank: bank
} }];

// CERO 01 :: Normalize the Alzheimer's Q&A workbook into per-category slices.
// Each specialist agent (section 5) is grounded ONLY in its own slice; the partition
// is what structurally prevents cross-category blending, not a prompt instruction.

const inp = $input.first().json;
const rows = inp.qa_rows || [];

const pick = (row, ...names) => {
  for (const n of names) {
    if (row[n] !== undefined && row[n] !== null && String(row[n]).trim() !== '') return row[n];
  }
  return '';
};

const slug = (s) => String(s).toLowerCase()
  .replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

const STOP = new Set(('a an the and or of to in is are was were be been for on with what how why when '
  + 'does do did can could should would it its this that these those my me you your i s not no yes if '
  + 'about from at as by there their they he she his her him them we us our').split(' '));

const tokenize = (s) => String(s || '').toLowerCase()
  .replace(/[^a-z0-9\s'-]/g, ' ').split(/\s+/)
  .map(t => t.replace(/^[-']+|[-']+$/g, ''))
  .filter(t => t.length > 2 && !STOP.has(t));

const entries = [];
rows.forEach((row, i) => {
  const category = String(pick(row, 'Category', 'category')).trim();
  if (!category) return;
  const question = String(pick(row, 'Question (Prompt)', 'Question', 'question')).trim();
  const shortA = String(pick(row, 'Short-Form Answer', 'short_form_answer')).trim();
  const longA = String(pick(row, 'Long-Form Answer', 'long_form_answer')).trim();
  const kw = String(pick(row, 'Keywords / Tags', 'Keywords', 'keywords')).trim();
  const discRaw = pick(row, 'Requires Medical Disclaimer', 'requires_medical_disclaimer');
  const disclaimer = discRaw === true || /^(true|yes|1)$/i.test(String(discRaw).trim());
  const keywords = kw ? kw.split(',').map(s => s.trim()).filter(Boolean) : [];

  entries.push({
    entry_id: 'qa_' + String(i + 1).padStart(3, '0'),
    category: category,
    category_key: slug(category),
    question: question,
    short_answer: shortA,
    long_answer: longA,
    keywords: keywords,
    requires_disclaimer: disclaimer,
    // retrieval surface: question + keywords carry the signal, answers add recall
    tokens: Array.from(new Set([].concat(
      tokenize(question), tokenize(keywords.join(' ')), tokenize(shortA)
    )))
  });
});

// document frequency for idf weighting at retrieval time
const df = {};
for (const e of entries) for (const t of new Set(e.tokens)) df[t] = (df[t] || 0) + 1;

const byCategory = {};
for (const e of entries) {
  const k = e.category_key;
  if (!byCategory[k]) byCategory[k] = { category: e.category, category_key: k, entry_ids: [], disclaimer_count: 0 };
  byCategory[k].entry_ids.push(e.entry_id);
  if (e.requires_disclaimer) byCategory[k].disclaimer_count += 1;
}

return [{ json: Object.assign({}, inp, {
  qa_entries: entries,
  qa_categories: Object.values(byCategory).map(c => Object.assign({}, c, { entry_count: c.entry_ids.length })),
  qa_df: df,
  qa_doc_count: entries.length
}) }];

// CERO 01 :: Validation gate. Everything the pipeline cannot administer or score is
// surfaced here rather than discovered mid-session.

const d = $input.first().json;
const findings = [];
const add = (sev, area, msg, detail) => findings.push({ severity: sev, area, message: msg, detail: detail || null });

// 1. point arithmetic per domain and per instrument
for (const dom of d.domain_index) {
  if (dom.item_count === 0) {
    add('blocker', 'instrument:' + dom.instrument_id,
      'Domain "' + dom.domain + '" produced no administrable items',
      { declared_max_points: dom.declared_max_points });
  } else if (dom.derived_max_points !== dom.declared_max_points) {
    add('error', 'instrument:' + dom.instrument_id,
      'Domain "' + dom.domain + '" declares ' + dom.declared_max_points +
      ' points but its items sum to ' + dom.derived_max_points,
      dom);
  }
  if (dom.agent_id === 'unmapped') {
    add('error', 'routing', 'Domain "' + dom.domain + '" has no owning sub-agent', dom);
  }
}

// 1b. items that reference a stimulus set the source file never supplies
const missingStim = d.item_bank.filter(x => x.stimulus_missing && !x.is_alternative);
if (missingStim.length) {
  add('blocker', 'instrument_data',
    missingStim.length + ' item(s) reference a stimulus set (word or object list) that is absent ' +
    'from the source file, so they cannot be administered or scored',
    missingStim.map(x => ({ instrument: x.instrument_id, domain: x.domain, label: x.label,
                            points: x.max_points, prompt: x.prompt_text })));
}

for (const inst of d.instrument_meta) {
  const doms = d.domain_index.filter(x => x.instrument_id === inst.id);
  const declaredSum = doms.reduce((a, b) => a + b.declared_max_points, 0);
  const derivedSum = doms.reduce((a, b) => a + b.derived_max_points, 0);
  const items = d.item_bank.filter(x => x.instrument_id === inst.id);
  const administrable = items.filter(x => !x.is_alternative && x.response_mode === 'verbal');
  const nonVerbal = items.filter(x => !x.is_alternative && x.response_mode !== 'verbal');

  if (declaredSum !== inst.declared_total_points) {
    add('error', 'instrument:' + inst.id,
      'Domain max_points sum to ' + declaredSum + ' but instrument declares total ' + inst.declared_total_points);
  }
  add('info', 'instrument:' + inst.id, 'Coverage summary', {
    declared_total: inst.declared_total_points,
    derived_from_items: derivedSum,
    items: items.length,
    verbal_points: administrable.reduce((a, b) => a + b.max_points, 0),
    non_verbal_points: nonVerbal.reduce((a, b) => a + b.max_points, 0),
    non_verbal_breakdown: nonVerbal.reduce((acc, x) => {
      acc[x.response_mode] = (acc[x.response_mode] || 0) + x.max_points; return acc;
    }, {})
  });
  if (nonVerbal.length) {
    add('blocker', 'channel',
      inst.id.toUpperCase() + ' has ' + nonVerbal.reduce((a, b) => a + b.max_points, 0) +
      ' points that cannot be administered or scored over a text-only channel',
      nonVerbal.map(x => ({ label: x.label, mode: x.response_mode, points: x.max_points })));
  }
  if (!inst.scoring_interpretation) {
    add('blocker', 'scoring', inst.id.toUpperCase() + ' has no scoring_interpretation table; ' +
      'the Documentation agent cannot produce banded output for it');
  }
}

// 2. assets required but not yet bound to a hosted file
const needed = Array.from(new Set(d.item_bank.filter(x => x.asset_id).map(x => x.asset_id)));
add('info', 'assets', 'Visual stimulus assets referenced by the item bank', needed);

// 3. education dataset
const expected = {
  overview: 3, history: 1, dementia_vs_alzheimer_s: 5, causes_and_risk_factors: 5,
  symptoms: 13, stages: 3, diagnosis: 5, treatment: 4,
  caregiver_support_and_communication: 3, lifestyle_and_risk_reduction: 2,
  legal_and_financial_planning: 3
};
for (const c of d.qa_categories) {
  const exp = expected[c.category_key];
  if (exp !== undefined && exp !== c.entry_count) {
    add('warn', 'education', 'Category "' + c.category + '" has ' + c.entry_count +
      ' entries; the deployment plan expects ' + exp);
  }
}
const missingAnswers = d.qa_entries.filter(e => !e.short_answer || !e.long_answer);
if (missingAnswers.length) {
  add('error', 'education', missingAnswers.length + ' Q&A entries are missing a short or long answer',
    missingAnswers.map(e => e.entry_id));
}
add('info', 'education', 'Dataset summary', {
  entries: d.qa_entries.length,
  categories: d.qa_categories.length,
  disclaimer_flagged: d.qa_entries.filter(e => e.requires_disclaimer).length
});

const counts = findings.reduce((a, f) => { a[f.severity] = (a[f.severity] || 0) + 1; return a; }, {});
return [{ json: Object.assign({}, d, {
  validation: { generated_at: new Date().toISOString(), counts, findings },
  has_blockers: (counts.blocker || 0) > 0
}) }];

// Fails loudly so a bad corpus can never be published silently.
const v = $input.first().json.validation;
const blockers = v.findings.filter(f => f.severity === 'blocker' || f.severity === 'error');
throw new Error('Corpus validation failed with ' + blockers.length +
  ' blocking findings:\n' + JSON.stringify(blockers, null, 2));

// CERO :: Emit the corpus artifact for durable storage in the cero_corpus data table.
const d = $input.first().json;
const cfg = $('Config').first().json;

// Inline image assets, read from the Drive folder at build time. Optional: a missing
// or empty folder must not break the corpus build, it just means picture items stay
// unadministrable and say so.
let assetMap = {};
try { assetMap = ($('Assets: To Data URIs').first().json || {}).assets || {}; } catch (e) { assetMap = {}; }

const bank = d.item_bank.slice().sort((a, b) =>
  a.instrument_id.localeCompare(b.instrument_id) ||
  a.domain_order - b.domain_order ||
  a.item_order - b.item_order);

const sequences = {};
for (const inst of d.instrument_meta) {
  sequences[inst.id] = bank
    .filter(x => x.instrument_id === inst.id && x.agent_id !== 'excluded' && !x.is_alternative)
    .map(x => x.item_uid);
}

const artifact = {
  corpus_version: cfg.CORPUS_VERSION,
  generated_at: new Date().toISOString(),
  source: { loaded_from: 'google_drive' },
  instruments: d.instrument_meta,
  domain_index: d.domain_index,
  item_bank: bank,
  administration_sequences: sequences,
  assets: assetMap,
  asset_ids: Object.keys(assetMap),
  qa_entries: d.qa_entries,
  qa_categories: d.qa_categories,
  qa_df: d.qa_df,
  qa_doc_count: d.qa_doc_count,
  validation: d.validation
};

// In-process cache for the rest of this execution only. The data table below is the
// durable source of truth.
const store = $getWorkflowStaticData('global');
store.corpus = artifact;
store.corpus_fetched_at = Date.now();

return [{ json: {
  artifact: artifact,
  payload: JSON.stringify(artifact),
  corpus_version: artifact.corpus_version,
  built_at: artifact.generated_at,
  validation: d.validation,
  has_blockers: d.has_blockers
} }];

// CERO 03 :: Corpus cache.
//
// Single-workflow build: the ingest island writes the corpus into this same static
// data store, so a cache hit is the normal path and CERO_CORPUS_URL is only a
// fallback for instances where the ingest island has not been run yet.
const store = $getWorkflowStaticData('global');
const input = $input.first().json;
const payload = typeof input.payload_json === 'string'
  ? JSON.parse(input.payload_json || '{}')
  : (input.payload_json || {});

// Presence is not usability. A stale build can leave a well-formed artifact with an
// empty item_bank in static data, and treating that as a hit means every session gets
// served an empty corpus until the ingest island is re-run. That failure used to
// surface as "No administration sequence for instrument mmse" deep in item selection.
const cached = store.corpus;
const usable = !!cached
  && Array.isArray(cached.item_bank) && cached.item_bank.length > 0
  && !!cached.administration_sequences
  && Object.keys(cached.administration_sequences).length > 0;

// No TTL when the corpus was written locally by the ingest island: it only changes
// when that island is re-run, and re-running it overwrites this store.
const fresh = usable && !payload.force_corpus_refresh;

return [{ json: {
  agent_id: input.agent_id,
  payload: payload,
  cache_hit: !!fresh,
  corpus_version: fresh ? store.corpus.corpus_version : null
} }];

// Single point where every branch picks up {agent_id, payload, corpus}.
const store = $getWorkflowStaticData('global');
const req = $input.first().json;
if (!store.corpus) throw new Error('Corpus unavailable after load attempt.');

// Fail here, with a message that names the fix, rather than letting an empty corpus
// travel downstream and surface as a confusing per-instrument lookup error.
const c = store.corpus;
const nItems = Array.isArray(c.item_bank) ? c.item_bank.length : 0;
const nSeq = c.administration_sequences ? Object.keys(c.administration_sequences).length : 0;
if (!nItems || !nSeq) {
  throw new Error('Corpus is present but empty (item_bank=' + nItems + ', administration_sequences=' + nSeq +
    ', version=' + (c.corpus_version || 'unknown') + '). Re-run the ingest island: Manual Trigger, or POST to cero/build.');
}

return [{ json: { agent_id: req.agent_id, payload: req.payload, corpus: store.corpus } }];

// CERO 03 :: Domain sub-agent registry (deployment plan, section 3).
// Each entry is independently editable and independently measurable: eval runs can
// target a single agent_id and attribute regressions to one prompt block.
//
// NOTE: this node must PASS THROUGH {agent_id, payload, corpus}. It sits between
// Corpus Ready and the agent_id router, so returning only the registry would strip
// the routing key and starve every downstream branch.
const inp = $input.first().json;

const REGISTRY = {
  orientation_agent: {
    title: 'Orientation Agent',
    owns: 'Orientation to time and place across MMSE and MoCA.',
    rules: [
      'Ask exactly one orientation probe per turn, in source order.',
      'Never volunteer, hint at, or confirm the correct date, day, season, place, city, or floor, before or after the response.',
      'If the patient answers a component you have not asked yet, credit it and skip that item rather than re-asking.',
      'Grade against the session clock and the session location supplied in context, not against your own assumptions.'
    ]
  },
  memory_recall_agent: {
    title: 'Memory & Recall Agent',
    owns: 'Registration, immediate recall, encoding trials, delayed recall.',
    rules: [
      'Present the word list exactly once per trial, in source order, and never re-reveal the words during a recall item.',
      'Run additional learning trials only up to the source-defined maximum, and only when the first trial was incomplete.',
      'Record the number of trials used; it is administration metadata, not score.',
      'For cued recall, apply cues in the source order (no cue, then category cue, then multiple choice) and record which cue produced the response.',
      'Score uncued recall for the total; cued performance is recorded separately for the memory index.'
    ]
  },
  attention_calc_agent: {
    title: 'Attention & Calculation Agent',
    owns: 'Serial subtraction, digit span, vigilance, spelling backward.',
    rules: [
      'Serial sevens: stop after exactly the source-defined number of subtractions. Do not continue past it.',
      'Score each subtraction against the patient\u2019s own previous answer, not against the ideal sequence, so a single early error does not zero the item.',
      'Use the spell-WORLD-backward alternative only if the patient cannot or will not perform the subtraction task, and score letters in correct order.',
      'Never confirm or correct an arithmetic answer during the item.'
    ]
  },
  language_naming_agent: {
    title: 'Language & Naming Agent',
    owns: 'Naming, repetition, reading, verbal fluency.',
    rules: [
      'Repetition items allow exactly one trial and are scored all-or-nothing per the source note.',
      'Naming items require the corresponding visual asset to have been delivered; if it was not, mark the item unadministered rather than guessing.',
      'Fluency items are time-bound; without an enforced timer, record the item as unadministered rather than estimating.',
      'Do not offer the target word, category cues, or first letters.'
    ]
  },
  visuospatial_exec_agent: {
    title: 'Visuospatial & Executive Agent',
    owns: 'Copying, drawing, multi-stage motor commands, writing.',
    rules: [
      'Deliver the full multi-stage command once, without segmenting it into separate prompts.',
      'Score drawing and motor items only from an actual captured artifact or an observer report; never infer them from a text description alone.',
      'If no artifact or observer report is available, mark the item unadministered with reason "channel_unsupported".'
    ]
  },
  abstraction_agent: {
    title: 'Abstraction Agent',
    owns: 'Similarity and abstraction items (MoCA and modified MMSE).',
    rules: [
      'Deliver the practice pair first when the source specifies one, coach only on the practice pair, and never coach on scored pairs.',
      'Award credit only for an abstract category response; concrete or functional similarities score per the source note.'
    ]
  }
};

return [{ json: Object.assign({}, inp, { registry: REGISTRY }) }];

// CERO 03 :: safety screen result -> routing decision.
//
// Three separate questions, deliberately not collapsed into one boolean:
//   interrupt_session  - do we stop the assessment turn
//   escalate_to_human  - does a person need to see this session
//   clinician_note     - worth recording, does not stop anything
//
// `reason` selects the response template downstream. `pause_kind` decides whether
// the patient can resume the session themselves.
const res = $input.first().json;
const payload = $('Corpus Ready').first().json.payload;

let out;
if (res && res.error) {
  // Fail closed: an unavailable safety screen must not silently pass the turn through.
  out = { risk_level: 'unknown', flags: [], trigger_summary: 'Safety screen unavailable: ' + JSON.stringify(res.error).slice(0, 200), confidence: 0 };
} else {
  const block = (res.content || []).find(b => b.type === 'tool_use');
  out = block ? block.input : { risk_level: 'unknown', flags: [], trigger_summary: 'Malformed safety response', confidence: 0 };
}

const level = out.risk_level;
const flags = Array.isArray(out.flags) ? out.flags : [];

const selfHarm     = level === 'high' || level === 'moderate';
const screenFailed = level === 'unknown';
const abuse        = flags.includes('abuse_disclosure');
const caregiver    = flags.includes('caregiver_crisis');
const acuteMedical = flags.includes('acute_medical');

// An acute_medical flag alongside risk_level none is, in this pipeline, almost always
// the presenting complaint being described during intake. It is recorded for the
// clinician but does not stop the session. If the model ALSO raised the risk level,
// treat it as real and interrupt.
const acuteIsUrgent = acuteMedical && (level === 'moderate' || level === 'high');

const interrupt = selfHarm || screenFailed || abuse || caregiver || acuteIsUrgent;

// Precedence matters: self-harm outranks everything, screen failure is technical
// and must not borrow crisis copy.
let reason = 'none';
if (selfHarm)           reason = 'self_harm';
else if (abuse)         reason = 'abuse';
else if (caregiver)     reason = 'caregiver';
else if (acuteIsUrgent) reason = 'acute_medical';
else if (screenFailed)  reason = 'screen_unavailable';

// hard: only a proctor clears it. The patient saying "I'm fine" must not.
// soft: the patient may resume on explicit confirmation.
let pauseKind = 'none';
if (reason === 'self_harm' || reason === 'abuse' || reason === 'caregiver' || reason === 'acute_medical') {
  pauseKind = 'hard';
} else if (reason === 'screen_unavailable') {
  pauseKind = 'soft';
}

return [{ json: { result: {
  risk_level: level,
  flags: flags,
  trigger_summary: out.trigger_summary || '',
  confidence: out.confidence || 0,

  interrupt_session: interrupt,
  escalate_to_human: selfHarm || abuse || caregiver || acuteIsUrgent,

  // recorded on the session, surfaced in the clinical note, does not stop the turn
  clinician_note: acuteMedical && !acuteIsUrgent
    ? { type: 'acute_medical_reported', summary: out.trigger_summary || '' }
    : null,

  reason: reason,
  pause_kind: pauseKind,
  screened_at: new Date().toISOString()
} } }];

// Uniform envelope back to the caller.
const j = $input.first().json;
return [{ json: {
  ok: true,
  agent_id: $('Corpus Ready').first().json.agent_id,
  corpus_version: $('Corpus Ready').first().json.corpus.corpus_version,
  result: j.result !== undefined ? j.result : j
} }];

// CERO 03 :: domain_ask - fully deterministic. No model call.
// Item wording comes verbatim from the corpus; nothing is reconstructed from memory.
// This is the single biggest protocol-adherence lever in the pipeline.
const { payload, corpus } = $input.first().json;
const instrumentId = payload.instrument_id;
const cursor = Number(payload.cursor || 0);

const sequence = (corpus.administration_sequences || {})[instrumentId];
if (!sequence) throw new Error('No administration sequence for instrument "' + instrumentId + '"');

const byUid = {};
for (const it of corpus.item_bank) byUid[it.item_uid] = it;

// Assets are inlined into the corpus as data URIs by the ingest island, so there is no
// base URL to build against and no host to depend on.
const ASSETS = corpus.assets || {};
const SUPPORTED = payload.supported_response_modes || ['verbal'];

// Modes where the patient cannot answer without first being shown something.
const NEEDS_STIMULUS = ['visual_stimulus', 'read_and_act', 'drawing'];

function shape(uid, idx) {
  const it = byUid[uid];
  const assetUri = it.asset_id ? ASSETS[it.asset_id] : null;

  const modeOk = SUPPORTED.indexOf(it.response_mode) !== -1;
  // an item whose stimulus set is absent from the corpus is unanswerable by construction
  const dataOk = it.administrable !== false;
  // a picture item with no picture is worse than a skipped one: it asks the patient to
  // name or copy something they were never shown
  const stimulusOk = NEEDS_STIMULUS.indexOf(it.response_mode) === -1 || !!assetUri;

  const supported = modeOk && dataOk && stimulusOk;
  const reason = !dataOk ? (it.blocking_reason || 'stimulus_missing')
               : (!modeOk ? 'channel_unsupported:' + it.response_mode
               : (!stimulusOk ? 'stimulus_asset_missing:' + (it.asset_id || 'none') : null));
  return {
    cursor: idx,
    item_uid: it.item_uid,
    agent_id: it.agent_id,
    domain: it.domain,
    label: it.label,
    prompt_text: it.prompt_text,
    administration_instructions: it.administration_instructions,
    max_points: it.max_points,
    scoring_note: it.scoring_note,
    scoring_levels: it.scoring_levels,
    expected_responses: it.expected_responses,
    stimulus: it.stimulus,
    response_mode: it.response_mode,
    administrable: supported,
    unadministered_reason: reason,
    asset: assetUri ? { asset_id: it.asset_id, url: assetUri } : null
  };
}

// Skip forward over anything this channel cannot administer, recording each skip so
// the clinical note can state exactly which points were never attempted.
const skipped = [];
let idx = cursor;
while (idx < sequence.length) {
  const candidate = shape(sequence[idx], idx);
  if (candidate.administrable) {
    const prevDomain = payload.previous_domain || null;
    return [{ json: { result: {
      status: 'item',
      item: candidate,
      next_cursor: idx + 1,
      domain_changed: prevDomain !== null && prevDomain !== candidate.domain,
      progress: { position: idx + 1, total: sequence.length },
      skipped: skipped
    } } }];
  }
  skipped.push({
    item_uid: candidate.item_uid,
    domain: candidate.domain,
    label: candidate.label,
    max_points: candidate.max_points,
    reason: candidate.unadministered_reason
  });
  idx += 1;
}

return [{ json: { result: {
  status: 'complete',
  item: null,
  next_cursor: idx,
  progress: { position: sequence.length, total: sequence.length },
  skipped: skipped
} } }];

// CERO 03 :: build the scoring request for the owning domain agent.
const { payload, corpus } = $input.first().json;
const registry = $('Agent Registry').first().json.registry;
const item = payload.item;
const agent = registry[item.agent_id] || { title: item.agent_id, owns: '', rules: [] };
const cfg = payload.config || {};

const att = payload.patient_attachment || null;
const hasImage = !!(att && att.is_image && att.data_uri);

const system = [
  'You are the ' + agent.title + ' inside a research cognitive-assessment pipeline.',
  'Scope: ' + agent.owns,
  '',
  'You are scoring ONE already-administered test item. You do not speak to the patient,',
  'you do not administer anything, and you do not see the running total. You return a',
  'score for this item only.',
  '',
  'Administration rules you enforce:',
  agent.rules.map(r => '- ' + r).join('\n'),
  '',
  'Hard constraints:',
  '- Score strictly against the scoring note and point ceiling supplied. Never exceed max_points.',
  '- Never award partial credit unless the scoring note or scoring levels define it.',
  '- You have no authority to interpret the score, name a condition, or comment on the patient\u2019s cognition.',
  '- If the response is ambiguous, unintelligible, or off-topic, set needs_review true and',
  '  explain in one sentence.',
  '- When stimulus_delivered is true, the image or card for this item WAS shown to the',
  '  patient before they answered. Do not withhold credit, and do not set needs_review,',
  '  on the grounds that stimulus delivery is undocumented or unconfirmed. Score the',
  '  response on its content alone. Only treat an item as unadministered when',
  '  stimulus_delivered is false and the item requires a stimulus.',
  '- Judge only the content of the response. Do not penalise spelling, typing, or phrasing',
  '  unless the item explicitly scores those.',
  hasImage ? '' : null,
  hasImage ? 'AN IMAGE FROM THE PATIENT IS ATTACHED TO THIS REQUEST.' : null,
  hasImage ? '- It is the patient\u2019s own work: their drawing, their handwriting, or a photo of a' : null,
  hasImage ? '  completed physical task. It is NOT the stimulus you showed them.' : null,
  hasImage ? '- Score what you actually see in it against the scoring note. For a copying item that' : null,
  hasImage ? '  means counting angles and checking the intersection; for a motor task it means' : null,
  hasImage ? '  checking the described actions were carried out.' : null,
  hasImage ? '- A typed claim that the patient did something is not evidence. The image is.' : null,
  hasImage ? '- If the image is too blurred, cropped, or dark to judge, set needs_review true rather' : null,
  hasImage ? '  than guessing.' : null
].filter(x => x !== null).join('\n');

const context = {
  item: {
    domain: item.domain,
    label: item.label,
    prompt_as_administered: item.prompt_text,
    administration_instructions: item.administration_instructions,
    max_points: item.max_points,
    scoring_note: item.scoring_note,
    scoring_levels: item.scoring_levels,
    expected_responses: item.expected_responses,
    stimulus: item.stimulus,
    stimulus_delivered: payload.stimulus_delivered === true,
    asset: item.asset || null
  },
  session_ground_truth: {
    // Orientation items are only scorable against known truth. Supplied by the caller.
    current_datetime_iso: payload.ground_truth && payload.ground_truth.current_datetime_iso || null,
    location: payload.ground_truth && payload.ground_truth.location || null,
    note: 'If a field needed to score this item is null, set needs_review true rather than assuming.'
  },
  patient_attachment: att
    ? { mime_type: att.mime_type, file_name: att.file_name, is_image: att.is_image, attached_to_this_request: hasImage }
    : null,
  prior_turns_for_this_item: payload.item_transcript || [],
  patient_response_verbatim: payload.patient_response
};

const schema = {
  type: 'object',
  properties: {
    points_awarded: { type: 'number', description: 'Integer 0..max_points' },
    max_points: { type: 'number' },
    scored_components: {
      type: 'array',
      description: 'Per-component credit where the item has parts (e.g. each subtraction, each recalled word).',
      items: { type: 'object', properties: {
        component: { type: 'string' }, credited: { type: 'boolean' }, note: { type: 'string' } },
        required: ['component', 'credited'] }
    },
    needs_review: { type: 'boolean' },
    needs_repeat_prompt: { type: 'boolean', description: 'True only if the source protocol permits re-prompting this item.' },
    administration_flags: { type: 'array', items: { type: 'string' } },
    rationale: { type: 'string', description: 'One or two sentences, clinician-facing, no diagnostic language.' }
  },
  required: ['points_awarded', 'max_points', 'needs_review', 'rationale']
};

return [{ json: { request_body: {
  model: cfg.MODEL_SCORING || 'gpt-5.6-terra',
  max_tokens: 1024,
  temperature: 0,
  system: system,
  messages: [{ role: 'user', content: 'Score this item.\n\n' + JSON.stringify(context, null, 2) }],
  tools: [{ name: 'emit_score', description: 'Return the item score.', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'emit_score' },
  // Consumed by the OpenAI node's image message slot. Empty string when there is no
  // patient image, so the slot resolves to nothing rather than a broken reference.
  patient_image_data_uri: hasImage ? att.data_uri : ''
} } }];

const res = $input.first().json;
const item = $('Corpus Ready').first().json.payload.item;

function toolInput(r) {
  if (r && r.error) throw new Error('Anthropic API error: ' + JSON.stringify(r.error));
  const block = (r.content || []).find(b => b.type === 'tool_use');
  if (!block) throw new Error('Model did not return the forced tool call. Raw: ' + JSON.stringify(r).slice(0, 600));
  return block.input;
}

const out = toolInput(res);
const max = Number(item.max_points) || 0;
// Never trust the model with the ceiling.
let pts = Math.round(Number(out.points_awarded) || 0);
if (!Number.isFinite(pts) || pts < 0) pts = 0;
if (pts > max) { pts = max; out.administration_flags = (out.administration_flags || []).concat('clamped_to_max'); }

return [{ json: { result: {
  item_uid: item.item_uid,
  agent_id: item.agent_id,
  domain: item.domain,
  label: item.label,
  points_awarded: pts,
  max_points: max,
  scored_components: out.scored_components || [],
  needs_review: !!out.needs_review,
  needs_repeat_prompt: !!out.needs_repeat_prompt,
  administration_flags: out.administration_flags || [],
  rationale: out.rationale || '',
  scored_at: new Date().toISOString()
} } }];

// CERO 03 :: Education Orchestrator - classify to one or more of the dataset categories.
const { payload, corpus } = $input.first().json;
const cfg = payload.config || {};
const cats = corpus.qa_categories.map(c => ({ category_key: c.category_key, category: c.category, entries: c.entry_count }));

const system = [
  'You route a patient or caregiver question to the correct specialist in an Alzheimer\u2019s education service.',
  'You do not answer the question.',
  '',
  'Choose only from the supplied category list. If the question spans two categories,',
  'split it into separate sub-questions and assign each to exactly one category.',
  'Never assign a sub-question to more than one category.',
  '',
  'Set depth to "long" only when the user explicitly asks for detail, explanation, background,',
  'or "tell me more". Otherwise "short".',
  '',
  'If the question is not covered by any category, set out_of_scope true and leave routes empty.',
  'Treat requests for a personal diagnosis, prognosis, or medication decision as out_of_scope:',
  'those are referrals, not education.'
].join('\n');

const schema = {
  type: 'object',
  properties: {
    routes: { type: 'array', items: { type: 'object', properties: {
      category_key: { type: 'string' },
      sub_question: { type: 'string' },
      confidence: { type: 'number' }
    }, required: ['category_key', 'sub_question', 'confidence'] } },
    depth: { type: 'string', enum: ['short', 'long'] },
    out_of_scope: { type: 'boolean' },
    out_of_scope_reason: { type: 'string' }
  },
  required: ['routes', 'depth', 'out_of_scope']
};

return [{ json: { request_body: {
  model: cfg.MODEL_ROUTING || 'claude-sonnet-5',
  max_tokens: 700,
  temperature: 0,
  system: system,
  messages: [{ role: 'user', content: JSON.stringify({
    question: payload.patient_message,
    recent_turns: (payload.recent_turns || []).slice(-4),
    categories: cats
  }, null, 2) }],
  tools: [{ name: 'emit_routes', description: 'Return routing decision.', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'emit_routes' }
} } }];

// CERO 03 :: Retrieval. Category-scoped lexical retrieval with idf weighting and a
// keyword-tag boost.
//
// Design note: the corpus is 47 curated Q&A pairs across 11 categories with explicit
// keyword tags. The hard category partition is applied FIRST, which is what structurally
// prevents a specialist from blending in another category's content (plan section 5) -
// a metadata filter, not a prompt instruction. Within a slice of 1-13 entries, lexical
// scoring over question + tags is deterministic, auditable and reproducible for expert
// raters, which vector similarity is not. See README for the vector-store swap point.

const ready = $('Corpus Ready').first().json;
const corpus = ready.corpus;
const payload = ready.payload;
const res = $input.first().json;

const block = (res.content || []).find(b => b.type === 'tool_use');
if (!block) throw new Error('Router did not return the forced tool call.');
const routing = block.input;

const STOP = new Set(('a an the and or of to in is are was were be been for on with what how why when '
  + 'does do did can could should would it its this that these those my me you your i s not no yes if '
  + 'about from at as by there their they he she his her him them we us our').split(' '));
const tokenize = (s) => String(s || '').toLowerCase()
  .replace(/[^a-z0-9\s'-]/g, ' ').split(/\s+/)
  .map(t => t.replace(/^[-']+|[-']+$/g, ''))
  .filter(t => t.length > 2 && !STOP.has(t));

const N = corpus.qa_doc_count || corpus.qa_entries.length;
const df = corpus.qa_df || {};
const idf = (t) => Math.log(1 + N / (1 + (df[t] || 0)));

const TOP_K = Number((payload.config || {}).RETRIEVAL_TOP_K || 3);

const retrieved = [];
for (const route of (routing.routes || [])) {
  const slice = corpus.qa_entries.filter(e => e.category_key === route.category_key);
  if (!slice.length) {
    retrieved.push({ route, entries: [], miss: 'unknown_category_key' });
    continue;
  }
  const qTokens = tokenize(route.sub_question);
  const qSet = new Set(qTokens);

  const scored = slice.map(e => {
    const eSet = new Set(e.tokens);
    let overlap = 0;
    for (const t of qSet) if (eSet.has(t)) overlap += idf(t);
    // exact keyword-tag hits are the strongest signal in this dataset
    let tagBoost = 0;
    for (const kw of e.keywords) {
      const k = kw.toLowerCase();
      if (k.length > 3 && String(route.sub_question).toLowerCase().indexOf(k) !== -1) tagBoost += 1.5;
    }
    const norm = Math.sqrt(qTokens.length || 1);
    return { entry: e, score: (overlap / norm) + tagBoost };
  }).sort((a, b) => b.score - a.score);

  const best = scored[0] ? scored[0].score : 0;
  // keep the top hit plus anything close to it, capped at TOP_K
  const keep = scored.filter((s, i) => i === 0 || (best > 0 && s.score >= best * 0.55)).slice(0, TOP_K);

  retrieved.push({
    route: route,
    weak_match: best < 0.5,
    entries: keep.map(s => ({
      entry_id: s.entry.entry_id,
      category: s.entry.category,
      question: s.entry.question,
      short_answer: s.entry.short_answer,
      long_answer: s.entry.long_answer,
      keywords: s.entry.keywords,
      requires_disclaimer: s.entry.requires_disclaimer,
      retrieval_score: Number(s.score.toFixed(4))
    }))
  });
}

const disclaimerRequired = retrieved.some(r => r.entries.some(e => e.requires_disclaimer));

return [{ json: {
  routing: routing,
  retrieved: retrieved,
  disclaimer_required: disclaimerRequired,
  any_weak_match: retrieved.some(r => r.weak_match),
  payload: payload
} }];

// CERO 03 :: Category specialist. Grounded ONLY in the retrieved slice.
const d = $input.first().json;
const payload = d.payload;
const cfg = payload.config || {};
const depth = d.routing.depth === 'long' ? 'long' : 'short';

const DISCLAIMER = 'This is general information, not medical advice. Please talk it through with a clinical professional who knows the specific situation.';

const system = [
  'You are a category specialist in an Alzheimer\u2019s education service. You answer only from the',
  'reference entries supplied to you in this request.',
  '',
  'Grounding rules:',
  '- Every factual claim must be traceable to a supplied entry. Do not add facts from your own knowledge,',
  '  even if you believe they are correct.',
  '- Do not import content from a category other than the one supplied.',
  '- If the supplied entries do not answer the question, say plainly that you do not have',
  '  information on that and suggest raising it with a clinical professional. Do not improvise.',
  '',
  'Depth: the requested depth is "' + depth + '".',
  '- short: answer at roughly the length and level of detail of the entry\u2019s short-form answer.',
  '- long: use the long-form answer\u2019s depth. Do not pad, and do not editorialise past the source.',
  '',
  'Safety rules that are not negotiable:',
  '- Never state or imply that the reader or their family member has, or does not have, any condition.',
  '- Never give a prognosis, a timeline, or a medication or dosing recommendation.',
  '- Never reference or infer anything about the reader\u2019s own test performance.',
  '',
  'If multiple sub-questions are supplied, answer each in its own short paragraph, in order,',
  'and do not blend the sources between them.',
  '',
  d.disclaimer_required
    ? 'One or more source entries is flagged as requiring a medical disclaimer. End your answer with exactly this sentence on its own line: ' + DISCLAIMER
    : 'No disclaimer flag is set on the source entries. Do not append a disclaimer.'
].join('\n');

const schema = {
  type: 'object',
  properties: {
    answer: { type: 'string' },
    used_entry_ids: { type: 'array', items: { type: 'string' } },
    unanswered: { type: 'boolean', description: 'True if the supplied entries did not cover the question.' },
    notes_for_reviewer: { type: 'string' }
  },
  required: ['answer', 'used_entry_ids', 'unanswered']
};

return [{ json: { request_body: {
  model: cfg.MODEL_EDUCATION || 'claude-sonnet-5',
  max_tokens: 1600,
  temperature: 0.2,
  system: system,
  messages: [{ role: 'user', content: JSON.stringify({
    original_question: payload.patient_message,
    depth: depth,
    reader_profile: {
      role: payload.profile && payload.profile.role || 'unspecified',
      education_level: payload.profile && payload.profile.education_level || null
    },
    routed_sub_questions: d.retrieved.map(r => ({
      sub_question: r.route.sub_question,
      category: r.entries[0] ? r.entries[0].category : r.route.category_key,
      reference_entries: r.entries.map(e => ({
        entry_id: e.entry_id, question: e.question,
        short_answer: e.short_answer, long_answer: e.long_answer
      }))
    }))
  }, null, 2) }],
  tools: [{ name: 'emit_answer', description: 'Return the grounded answer.', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'emit_answer' }
} } }];

const res = $input.first().json;
const d = $('Retrieve: Category Slice').first().json;

if (d.routing.out_of_scope) {
  return [{ json: { result: {
    kind: 'education',
    patient_text: 'That is outside what I can help with here. A clinical professional who knows the situation is the right person for that question.',
    out_of_scope: true,
    reason: d.routing.out_of_scope_reason || '',
    used_entry_ids: [], routes: [], disclaimer_required: false
  } } }];
}

const block = (res.content || []).find(b => b.type === 'tool_use');
if (!block) throw new Error('Specialist did not return the forced tool call.');
const out = block.input;

// Enforce the disclaimer in code rather than trusting the model to remember it.
const DISCLAIMER = 'This is general information, not medical advice. Please talk it through with a clinical professional who knows the specific situation.';
let text = String(out.answer || '').trim();
if (d.disclaimer_required && text.indexOf(DISCLAIMER) === -1) {
  text = text + '\n\n' + DISCLAIMER;
}

// Grounding check: every claimed entry id must exist in what was actually retrieved.
const allowed = new Set([].concat.apply([], d.retrieved.map(r => r.entries.map(e => e.entry_id))));
const claimed = (out.used_entry_ids || []);
const ungrounded = claimed.filter(id => !allowed.has(id));

return [{ json: { result: {
  kind: 'education',
  patient_text: text,
  out_of_scope: false,
  unanswered: !!out.unanswered,
  used_entry_ids: claimed,
  ungrounded_entry_ids: ungrounded,
  weak_retrieval: !!d.any_weak_match,
  routes: d.retrieved.map(r => ({ category_key: r.route.category_key, sub_question: r.route.sub_question,
                                  entry_ids: r.entries.map(e => e.entry_id) })),
  disclaimer_required: d.disclaimer_required,
  notes_for_reviewer: out.notes_for_reviewer || ''
} } }];

// CERO 03 :: Tone & Empathy Agent (plan section 4.1).
//
// Critical constraint the plan does not resolve: rewriting an instrument's item wording
// would itself be a protocol violation. So verbatim spans are fenced and the agent may
// only touch the scaffolding around them. The fence is verified in code after the call.
const { payload } = $input.first().json;
const cfg = payload.config || {};
const profile = payload.profile || {};

const system = [
  'You are the tone pass for a cognitive-assessment and education service used by older adults',
  'and their caregivers. You rewrite phrasing only. You never change meaning, content, or scoring.',
  '',
  'ABSOLUTE RULE: text between <<VERBATIM>> and <</VERBATIM>> is standardised test wording.',
  'Reproduce it character for character, including the fence markers. Do not rephrase, expand,',
  'shorten, translate, correct, or re-punctuate anything inside the fence.',
  '',
  'Outside the fence:',
  '- Warm, calm, unhurried. Speak to an adult, never down to one.',
  '- Short sentences. Plain words. Reading level appropriate to the stated education level.',
  '- No praise or evaluation of answers ("great job", "that\u2019s right", "close"). It biases the test',
  '  and reveals scoring.',
  '- No hints, examples, category cues, multiple-choice options, or first letters.',
  '- Remove anything that reveals internal state: scores, running totals, cutoffs, bands, item counts,',
  '  which domain is active, how many items remain, instructions meant for the administrator,',
  '  or the fact that this is being scored at all.',
  '- No emoji. No exclamation marks. At most one short sentence of framing before the item.',
  '- Do not add a question of your own. Do not ask how they are feeling mid-item.',
  '',
  'Accessibility adjustments to apply when the profile calls for them: ' +
    JSON.stringify(profile.accessibility_needs || []),
  '',
  'Return the rewritten message only.'
].join('\n');

const schema = {
  type: 'object',
  properties: {
    rewritten_text: { type: 'string' },
    removed_leaks: { type: 'array', items: { type: 'string' },
      description: 'Short description of anything you stripped because it revealed internal state.' }
  },
  required: ['rewritten_text']
};

return [{ json: { request_body: {
  model: cfg.MODEL_TONE || 'claude-haiku-4-5-20251001',
  max_tokens: 1600,
  temperature: 0.3,
  system: system,
  messages: [{ role: 'user', content: JSON.stringify({
    draft: payload.draft_text,
    reader: {
      role: profile.role || 'patient',
      education_level: profile.education_level || null,
      preferred_name: profile.preferred_name || null,
      accessibility_needs: profile.accessibility_needs || []
    }
  }, null, 2) }],
  tools: [{ name: 'emit_text', description: 'Return the rewritten message.', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'emit_text' }
} } }];

const res = $input.first().json;
const payload = $('Corpus Ready').first().json.payload;
const draft = String(payload.draft_text || '');

const FENCE = /<<VERBATIM>>([\s\S]*?)<<\/VERBATIM>>/g;
const spans = (s) => { const out = []; let m; const re = new RegExp(FENCE); while ((m = re.exec(s))) out.push(m[1]); return out; };

let text = draft, tampered = false, leaks = [];
const block = (res.content || []).find(b => b.type === 'tool_use');

if (res && res.error) {
  // Tone is cosmetic. If it fails, deliver the draft rather than dropping the turn.
  tampered = true;
  leaks = ['tone_agent_unavailable'];
} else if (block) {
  const candidate = String(block.input.rewritten_text || '');
  const before = spans(draft), after = spans(candidate);
  const intact = before.length === after.length && before.every((v, i) => v === after[i]);
  if (intact && candidate.trim()) {
    text = candidate;
    leaks = block.input.removed_leaks || [];
  } else {
    // Verbatim protocol text was altered. Reject the rewrite entirely.
    tampered = true;
    leaks = ['verbatim_fence_violation'];
  }
}

// strip the fences before the text reaches the patient
text = text.replace(/<<\/?VERBATIM>>/g, '');

return [{ json: { result: {
  kind: 'tone',
  text: text.trim(),
  rewrite_applied: !tampered,
  fallback_reason: tampered ? leaks[0] : null,
  removed_leaks: leaks
} } }];

// CERO 03 :: Clinical Documentation & Safety Agent - scoring and interpretation.
// Deterministic. The model is used only to narrate; it never computes or bands a score.
const { payload, corpus } = $input.first().json;
const results = payload.item_results || [];
const skipped = payload.skipped_items || [];
const instrument = corpus.instruments.find(i => i.id === payload.instrument_id);
if (!instrument) throw new Error('Unknown instrument: ' + payload.instrument_id);

const raw = results.reduce((a, r) => a + (Number(r.points_awarded) || 0), 0);
const attemptedMax = results.reduce((a, r) => a + (Number(r.max_points) || 0), 0);
const skippedMax = skipped.reduce((a, s) => a + (Number(s.max_points) || 0), 0);
const declaredMax = Number(instrument.declared_total_points) || 0;

// Per-domain rollup
const domains = {};
for (const r of results) {
  const k = r.domain;
  if (!domains[k]) domains[k] = { domain: k, agent_id: r.agent_id, awarded: 0, possible: 0, items: 0, flagged: 0 };
  domains[k].awarded += Number(r.points_awarded) || 0;
  domains[k].possible += Number(r.max_points) || 0;
  domains[k].items += 1;
  if (r.needs_review) domains[k].flagged += 1;
}
for (const s of skipped) {
  const k = s.domain;
  if (!domains[k]) domains[k] = { domain: k, agent_id: null, awarded: 0, possible: 0, items: 0, flagged: 0 };
  domains[k].not_administered = (domains[k].not_administered || 0) + (Number(s.max_points) || 0);
}

// Interpretation bands, applied only from the source tables.
function bands(inst, score, educationYears) {
  const si = inst.scoring_interpretation;
  const out = [];
  if (!si) return [{ method: 'none', interpretation: 'No interpretation table available for this instrument in the source data.' }];

  const methods = Array.isArray(si) ? [{ method: 'Range', rules: si }] : (si.methods || []);
  for (const m of methods) {
    for (const rule of (m.rules || si)) {
      if (rule.score_range) {
        if (score >= rule.score_range.min && score <= rule.score_range.max) {
          out.push({ method: m.method || 'Range', interpretation: rule.interpretation, rule: rule });
        }
      } else if (typeof rule.score === 'string') {
        const mm = rule.score.match(/^(<=|>=|<|>|=)?\s*(\d+)$/);
        if (mm) {
          const op = mm[1] || '='; const n = Number(mm[2]);
          const hit = op === '<' ? score < n : op === '>' ? score > n
            : op === '<=' ? score <= n : op === '>=' ? score >= n : score === n;
          if (hit) out.push({ method: m.method || 'Rule', interpretation: rule.interpretation, rule: rule });
        }
      }
    }
  }
  return out;
}

// MoCA education adjustment, applied only when the source declares one.
let adjusted = raw, adjustmentNote = null;
const eduYears = payload.profile && Number(payload.profile.education_years);
if (instrument.education_adjustment && Number.isFinite(eduYears) && eduYears <= 12) {
  adjusted = Math.min(raw + 1, declaredMax);
  adjustmentNote = 'One point added for 12 or fewer years of formal education, per the instrument\u2019s stated adjustment.';
}

const partial = skippedMax > 0 || attemptedMax < declaredMax;

return [{ json: {
  scoring: {
    instrument_id: instrument.id,
    instrument_name: instrument.name,
    corpus_version: corpus.corpus_version,
    raw_score: raw,
    adjusted_score: adjusted,
    adjustment_note: adjustmentNote,
    points_attempted: attemptedMax,
    points_not_administered: skippedMax,
    instrument_max: declaredMax,
    partial_administration: partial,
    interpretation: partial
      ? [{ method: 'suppressed', interpretation: 'Interpretation bands are not applied: the instrument was only partially administered (' + attemptedMax + ' of ' + declaredMax + ' points). A partial score is not comparable to the published cutoffs.' }]
      : bands(instrument, adjusted, eduYears),
    per_domain: Object.values(domains).sort((a, b) => a.domain.localeCompare(b.domain)),
    items_flagged_for_review: results.filter(r => r.needs_review).length,
    not_administered: skipped
  },
  payload: payload
} }];

// The model narrates the already-computed numbers. It cannot change them.
const d = $input.first().json;
const cfg = d.payload.config || {};

const system = [
  'You write the clinician-facing session note for a research cognitive-assessment pipeline.',
  'All numbers, bands, and totals are already computed and supplied. Reproduce them exactly.',
  'You may not recompute, round, reinterpret, or extrapolate any figure.',
  '',
  'Hard rules:',
  '- Never name a disease, disorder, or diagnosis. Not as a conclusion, not as a possibility,',
  '  not as a rule-out, not as a differential, and not as a list of conditions the pattern',
  '  might be consistent with. Use only the interpretation text supplied from the',
  '  instrument\u2019s own table. Naming candidate conditions is the clinician\u2019s job, not yours.',
  '- Never write a prognosis, a severity judgement of your own, or a treatment or referral',
  '  recommendation beyond "refer to a clinical professional for interpretation".',
  '- Include no identifying details beyond the session id and the non-identifying profile fields supplied.',
  '- State plainly which items were not administered and why, and that the total is therefore partial',
  '  where the supplied data says so.',
  '- Flag items marked for review and any administration flags.',
  '',
  'Symptom summary section:',
  '- Organise what the patient reported at intake (presenting concerns, complaints, symptoms)',
  '  into clear clinical categories: memory, language, orientation, executive function,',
  '  attention, visuospatial, mood or behaviour, functional impact on daily living.',
  '- Separately note observable patterns from the session itself, tied to specific domains and',
  '  items, for example "delayed recall 0 of 3 while orientation to place was 5 of 5".',
  '- Describe the pattern. Do not label it. Say what was reported and what was observed, and',
  '  let the clinician draw the inference.',
  '- Where a reported symptom has no corresponding item in the administered instrument, say so,',
  '  since that is a gap the clinician may want to follow up directly.',
  '',
  'Format: concise clinical markdown. Sections: Summary, Score, Per-domain breakdown,',
  'Symptom summary, Not administered, Items flagged for review, Administration notes. No preamble.'
].join('\n');

const schema = {
  type: 'object',
  properties: {
    note_markdown: { type: 'string' },
    patient_closing_message: { type: 'string',
      description: 'Plain, warm, 2-3 sentences. Confirms the session is finished and that a professional will review it. Contains NO score, NO band, NO evaluation of performance.' }
  },
  required: ['note_markdown', 'patient_closing_message']
};

return [{ json: { request_body: {
  model: cfg.MODEL_DOCUMENTATION || 'gpt-5.6-terra',
  max_tokens: 2000,
  temperature: 0.1,
  system: system,
  messages: [{ role: 'user', content: JSON.stringify({
    session_id: d.payload.session_id,
    profile_non_identifying: {
      age_band: d.payload.profile && d.payload.profile.age_band || null,
      sex: d.payload.profile && d.payload.profile.sex || null,
      education_level: d.payload.profile && d.payload.profile.education_level || null,
      accessibility_needs: d.payload.profile && d.payload.profile.accessibility_needs || [],
      presenting_concerns: d.payload.profile && d.payload.profile.presenting_concerns || []
    },
    scoring: d.scoring,
    item_results: (d.payload.item_results || []).map(r => ({
      domain: r.domain, label: r.label, awarded: r.points_awarded, max: r.max_points,
      needs_review: r.needs_review, flags: r.administration_flags, rationale: r.rationale
    })),
    safety_events: d.payload.safety_events || []
  }, null, 2) }],
  tools: [{ name: 'emit_note', description: 'Return the clinical note.', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'emit_note' }
} } }];

const res = $input.first().json;
const d = $('Doc: Score & Interpret').first().json;

const block = (res.content || []).find(b => b.type === 'tool_use');
if (!block) throw new Error('Documentation agent did not return the forced tool call.');
const out = block.input;

// Last line of defence on the patient-facing string: no numbers, no bands.
const BANNED = /\b(score|scored|points?|out of \d|\d+\s*\/\s*\d+|impairment|normal cognition|abnormal|dementia|alzheimer)/i;
let closing = String(out.patient_closing_message || '').trim();
if (!closing || BANNED.test(closing)) {
  closing = 'That is everything for today, and you are all finished. Thank you for taking the time to work through it with me. A clinical professional will look over the session and follow up with you.';
}

return [{ json: { result: {
  kind: 'documentation',
  scoring: d.scoring,
  clinical_note_markdown: out.note_markdown || '',
  patient_text: closing,
  generated_at: new Date().toISOString()
} } }];

// CERO 02 :: Load or initialise session state.
//
// State lives in this workflow's static data. Single n8n instance only, lost on
// restart, last-write-wins under concurrent turns for one session.
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

const cfg = $('Config1').first().json;
// Read the trigger payload from Input: Normalize explicitly. Config1 sits between the
// trigger and this node, so reading $json here would pick up config values, not the
// message.
const body = $('Input: Normalize').first().json;

const sessionId = body.session_id;
const message = typeof body.message === 'string' ? body.message : '';
const isChat = !!body.is_chat;

// prune idle sessions so static data cannot grow without bound
const TTL = Number(cfg.SESSION_TTL_HOURS) * 3600 * 1000;
const now = Date.now();
for (const [k, v] of Object.entries(store.sessions)) {
  if (!v.updated_at || (now - v.updated_at) > TTL) delete store.sessions[k];
}

let s = store.sessions[sessionId];
if (!s) {
  s = {
    session_id: sessionId,
    created_at: now,
    updated_at: now,
    mode: 'intake',
    profile: { role: null, preferred_name: null, age_band: null, education_level: null,
               education_years: null, accessibility_needs: [], presenting_concerns: [], consent: null },
    intake_step: 0,
    assessor: { instrument_id: null, cursor: 0, awaiting: null, item_results: [],
                skipped_items: [], previous_domain: null, started_at: null },
    education: { turns: 0 },
    safety_events: [],
    transcript: [],
    score_released: false,
    turn_count: 0
  };
  store.sessions[sessionId] = s;
}

// caller may force a track; otherwise stay in whatever track the session is in
const requestedMode = String(body.mode || '').trim();
if (requestedMode && ['assessor', 'educator'].indexOf(requestedMode) !== -1 && s.mode !== 'intake' && s.mode !== 'complete') {
  s.mode = requestedMode;
}

s.turn_count += 1;
if (message) s.transcript.push({ role: 'patient', text: message, at: now });
if (s.transcript.length > 40) s.transcript = s.transcript.slice(-40);

const config = {
  MODEL_SAFETY: cfg.MODEL_SAFETY, MODEL_SCORING: cfg.MODEL_SCORING,
  MODEL_ROUTING: cfg.MODEL_ROUTING, MODEL_EDUCATION: cfg.MODEL_EDUCATION,
  MODEL_TONE: cfg.MODEL_TONE, MODEL_DOCUMENTATION: cfg.MODEL_DOCUMENTATION,
  RETRIEVAL_TOP_K: cfg.RETRIEVAL_TOP_K
};

return [{ json: {
  session_id: sessionId,
  message: message,
  is_chat: isChat,
  mode: s.mode,
  state: s,
  config: config,
  cfg: cfg,
  safety_payload: JSON.stringify({
    patient_message: message,
    mode: s.mode,
    recent_turns: s.transcript.slice(-6),
    config: config
  })
} }];

// executeWorkflow returns only the agent envelope; re-attach the session context.
const agent = $input.first().json;
const ctx = $('Session: Load').first().json;
return [{ json: Object.assign({}, ctx, { safety: agent.result }) }];

// CERO 02 :: Safety interrupt (plan section 4.3 / section 7 rule 3).
//
// Fixed templates, not model output. A generated response is the wrong tool on the one
// turn that must be predictable.
//
// Branches on safety.reason. The 988 Suicide & Crisis Lifeline appears ONLY on the
// self-harm branch. Routing every interrupt through suicide-crisis copy is how a patient
// reporting ordinary memory symptoms ended up being handed a suicide hotline.
const d = $input.first().json;
const screen = d.safety;
const cfg = $('Config1').first().json;
const state = $('Session: Load').first().json.state;

const EMERGENCY = 'If you are in immediate danger, please call 911 or go to your nearest emergency room.';
const LIFELINE  = 'You can reach the 988 Suicide & Crisis Lifeline any time by calling or texting 988.';
const ALZ       = 'The Alzheimer\u2019s Association helpline is open any time, day or night, at 1-800-272-3900.';
const ONSITE    = 'Please speak with a staff member here, or ask for the social worker on duty.';

const TEMPLATES = {
  self_harm: {
    core: 'I want to stop here for a moment, because what you just said matters more than anything '
        + 'else we were doing. I am sorry you are carrying this. You do not have to carry it by '
        + 'yourself, and talking to a person who can actually be there with you would help more '
        + 'than anything I can offer.',
    resources: [EMERGENCY, LIFELINE, ALZ],
    close: 'We can leave the questions for another day. There is no rush, and nothing here needs finishing today.'
  },

  acute_medical: {
    core: 'I want to pause the questions here. What you described sounds like it may have started '
        + 'suddenly, and that is worth having someone look at soon rather than later.',
    resources: [EMERGENCY, 'If you are here in the building, please tell a staff member now.'],
    close: 'The questions can wait. Getting this looked at comes first.'
  },

  abuse: {
    core: 'Thank you for telling me. I want to stop the questions here, because what you have '
        + 'described needs a person, not a questionnaire.',
    resources: [EMERGENCY, ONSITE],
    close: 'Nothing you have said here is your fault, and you do not have to sort it out on your own.'
  },

  caregiver: {
    core: 'I want to stop here. Caring for someone through this is genuinely hard, and what you '
        + 'have described is worth talking through with a person who can help you plan.',
    resources: [ALZ, ONSITE],
    close: 'The questions can wait. There is no rush on any of this today.'
  },

  screen_unavailable: {
    // Technical failure. No crisis resources: nothing has happened to this patient,
    // and offering a hotline here would be alarming and wrong.
    core: 'I have hit a technical problem on my end and cannot safely continue right now. '
        + 'This is not about anything you said.',
    resources: [],
    close: 'Please let a staff member know, and we can pick this up shortly.'
  }
};

const reason = (screen && screen.reason) || 'self_harm';
const tpl = TEMPLATES[reason] || TEMPLATES.self_harm;

const parts = [tpl.core];
if (tpl.resources.length) { parts.push('', tpl.resources.join('\n')); }
parts.push('', tpl.close);
const text = parts.join('\n');

state.safety_events.push({
  at: Date.now(),
  turn: state.turn_count,
  risk_level: screen.risk_level,
  flags: screen.flags,
  reason: reason,
  trigger_summary: screen.trigger_summary,
  escalated: screen.escalate_to_human,
  session_mode_at_event: state.mode
});

// Remember where to return to, so a proctor-cleared pause can resume mid-assessment
// instead of restarting the instrument.
state.mode_before_pause = state.mode;
state.mode = 'paused_safety';
state.pause_kind = (screen && screen.pause_kind) || 'hard';
state.pause_reason = reason;

return [{ json: {
  kind: 'crisis',
  patient_text: text,
  skip_tone: true,
  human_review_required: true,
  escalate_to_human: !!screen.escalate_to_human,
  safety: screen,
  state: state,
  config: $('Session: Load').first().json.config
} }];

// CERO 02 :: Decide whether this turn is a response to score, or a fresh item to ask.
const d = $input.first().json;
const state = d.state;
const cfg = $('Config1').first().json;
const msg = (d.message || '').trim();
const a = state.assessor;

// A patient can answer a drawing or motor item by uploading a photo instead of typing,
// so an attachment on its own is a scorable response even with an empty message.
let attachment = null;
try { attachment = ($('Input: Normalize').first().json || {}).attachment || null; } catch (e) { attachment = null; }

const needsScoring = !!(a.awaiting && (msg || attachment));

const supported = String(cfg.SUPPORTED_RESPONSE_MODES || 'verbal')
  .split(',').map(s => s.trim()).filter(Boolean);

const base = {
  state: state,
  config: d.config,
  message: msg,
  has_attachment: !!attachment,
  needs_scoring: needsScoring,
  ask_payload: JSON.stringify({
    instrument_id: a.instrument_id,
    cursor: a.cursor,
    previous_domain: a.previous_domain,
    asset_base_url: cfg.ASSET_BASE_URL,
    supported_response_modes: supported,
    config: d.config
  })
};

if (!needsScoring) return [{ json: base }];

// The scorer must be told the stimulus actually reached the patient. Without this it
// sees a naming or reading item, finds no evidence the image was shown, and zeroes the
// item with "visual asset delivery not documented" even when the answer was correct.
//
// The stimulus asset URL is a base64 data URI and can run to tens of kilobytes, so only
// the id and a delivered flag are forwarded. The scorer never needs the stimulus pixels;
// it scores the patient's response. The PATIENT'S OWN upload is different: that is the
// evidence being scored, so its data URI is passed through in full.
const item = a.awaiting.item || {};
const delivered = !!(item.asset && item.asset.url);
const itemForScoring = Object.assign({}, item, {
  asset: item.asset ? { asset_id: item.asset.asset_id, delivered: true } : null
});

return [{ json: Object.assign(base, {
  score_payload: JSON.stringify({
    item: itemForScoring,
    stimulus_delivered: delivered,
    patient_response: msg,
    patient_attachment: attachment
      ? {
          mime_type: attachment.mime_type,
          file_name: attachment.file_name,
          is_image: attachment.is_image,
          data_uri: attachment.data_uri
        }
      : null,
    item_transcript: a.awaiting.transcript || [],
    ground_truth: {
      current_datetime_iso: new Date().toISOString(),
      location: cfg.SESSION_LOCATION || null
    },
    config: d.config
  })
}) }];

const d = $input.first().json;
const state = d.state;
state.education.turns += 1;
return [{ json: { state: state, config: d.config, edu_payload: JSON.stringify({
  patient_message: d.message,
  recent_turns: state.transcript.slice(-6),
  profile: state.profile,
  config: d.config
}) } }];

const d = $input.first().json;
const state = d.state;
const msg = (d.message || '').trim().toLowerCase();

// Proctor override. Set PROCTOR_RESUME_PHRASE in Config1. Deliberately not something
// a patient would type by accident. A hard pause must not be clearable by the patient
// saying they are fine.
const RESUME_PHRASE = ((d.config && d.config.PROCTOR_RESUME_PHRASE) || 'cero resume override').toLowerCase();
const SOFT_RESUME = ['continue', 'resume', 'yes', 'ready', 'im ready', "i'm ready", 'keep going'];

if (state.mode === 'paused_safety') {
  const proctorClear = RESUME_PHRASE.length > 0 && msg.includes(RESUME_PHRASE);
  const softClear = state.pause_kind === 'soft' && SOFT_RESUME.some(p => msg === p || msg.startsWith(p));

  if (proctorClear || softClear) {
    state.mode = state.mode_before_pause || 'intake';
    delete state.mode_before_pause;
    delete state.pause_kind;
    delete state.pause_reason;
    state.safety_events.push({
      at: Date.now(),
      turn: state.turn_count,
      reason: 'resume',
      cleared_by: proctorClear ? 'proctor' : 'patient_soft'
    });
    return [{ json: { kind: 'resumed', draft_text: 'Thank you. Picking up where we left off.', skip_tone: true, state: state, config: d.config } }];
  }

  const text = state.pause_kind === 'soft'
    ? 'We stopped a moment ago because of a problem on my end. Say "continue" when you would like to try again.'
    : 'We paused here earlier. Someone from the care team needs to pick this up with you before we carry on.';
  return [{ json: { kind: 'inactive', draft_text: text, skip_tone: true, state: state, config: d.config } }];
}

const msgOut = state.mode === 'complete'
  ? 'We already finished the questions for this session. If you have something you would like to understand better, I am happy to talk it through.'
  : 'This session is not active. Please start a new one when you are ready.';

return [{ json: { kind: 'inactive', draft_text: msgOut, skip_tone: true, state: state, config: d.config } }];

// CERO 02 :: Record the item result and advance the cursor.
const scored = $input.first().json.result;
const prev = $('Assessor: Resolve Turn').first().json;
const state = prev.state;
const cfg = $('Config1').first().json;
const a = state.assessor;
const awaiting = a.awaiting;

const MAX_ATTEMPTS = Number(cfg.MAX_ITEM_ATTEMPTS) || 1;
const attempts = (awaiting.attempts || 1);

// Re-prompt only when the source protocol allows it and we are under the attempt cap.
if (scored.needs_repeat_prompt && attempts < MAX_ATTEMPTS) {
  awaiting.attempts = attempts + 1;
  awaiting.transcript = (awaiting.transcript || []).concat([{ response: prev.message, partial: scored }]);
  a.cursor = awaiting.item.cursor;   // re-serve the same item
} else {
  a.item_results.push(Object.assign({}, scored, { attempts: attempts }));
  a.previous_domain = awaiting.item.domain;
  a.cursor = awaiting.next_cursor;
  a.awaiting = null;
}

return [{ json: {
  state: state,
  config: prev.config,
  needs_scoring: false,
  ask_payload: JSON.stringify({
    instrument_id: a.instrument_id,
    cursor: a.cursor,
    previous_domain: a.previous_domain,
    asset_base_url: cfg.ASSET_BASE_URL,
    supported_response_modes: String(cfg.SUPPORTED_RESPONSE_MODES || 'verbal').split(',').map(s => s.trim()).filter(Boolean),
    config: prev.config
  })
} }];

const upstream = $('Assessor: Resolve Turn').first().json;
const ask = $input.first().json.result;
const state = upstream.state;
const a = state.assessor;
if (ask.skipped && ask.skipped.length) a.skipped_items = a.skipped_items.concat(ask.skipped);
return [{ json: {
  state: state, config: upstream.config,
  doc_payload: JSON.stringify({
    session_id: state.session_id,
    instrument_id: a.instrument_id,
    profile: state.profile,
    item_results: a.item_results,
    skipped_items: a.skipped_items,
    safety_events: state.safety_events,
    config: upstream.config
  })
} }];

// CERO 02 :: Build the patient-facing draft for the next item.
//
// The item's own wording is fenced so the Tone agent cannot alter it.
//
// STATE SOURCE MATTERS. This used to read $('Assessor: Resolve Turn'), which is the
// state as it looked BEFORE the previous answer was scored. Assessor: Apply Score
// pushes to item_results and advances the cursor on its own copy, and re-reading the
// pre-scoring state here threw all of that away every single turn. That is why a full
// session ended with item_results: [], cursor: 0 and a raw score of 0 out of 30.
// Apply Score only runs on turns that scored something, so fall back when it is absent.
let upstream;
try {
  upstream = $('Assessor: Apply Score').first().json;
} catch (e) {
  upstream = $('Assessor: Resolve Turn').first().json;
}

const ask = $input.first().json.result;
const state = upstream.state;
const a = state.assessor;

// record anything the channel could not administer
if (ask.skipped && ask.skipped.length) {
  a.skipped_items = a.skipped_items.concat(ask.skipped);
}

const item = ask.item;
a.awaiting = { item: item, next_cursor: ask.next_cursor, attempts: 1, transcript: [] };

const parts = [];
if (ask.domain_changed && a.item_results.length > 0) {
  parts.push('Here is the next part.');
}

// The stimulus word list has to reach the patient or the item is unanswerable.
// Registration was asking the patient to repeat three objects without ever naming
// them, because only prompt_text was emitted and the stimulus was dropped.
//
// It must NEVER be rendered on a recall item. Recall carries the same list so the
// scorer can mark the answer against it, so printing it there hands the patient the
// answer and destroys the item. Recall domains are identified by name, which holds
// for MMSE Recall, MoCA Delayed Recall, and the modified MMSE's cued recall items.
const wordList = item.stimulus && Array.isArray(item.stimulus.word_list)
  ? item.stimulus.word_list
  : null;
const isRecallItem = /recall/i.test(item.domain || '');
const presentWords = !!(wordList && wordList.length && !isRecallItem);

let itemText = item.prompt_text;
if (presentWords) {
  // Inside the fence: the exact words and their order are test content, not phrasing,
  // and the Tone agent must not paraphrase or reorder them.
  itemText = wordList.join(', ') + '\n\n' + itemText;
}

// Stimulus image, inlined as a data URI by the ingest island. It goes inside the fence
// so the Tone agent cannot drop or reword the markdown, and after the prompt so the
// patient reads the instruction first.
const assetUrl = item.asset && item.asset.url ? item.asset.url : null;
if (assetUrl) {
  itemText = itemText + '\n\n![' + (item.asset.asset_id || 'stimulus') + '](' + assetUrl + ')';
}

parts.push('<<VERBATIM>>' + itemText + '<</VERBATIM>>');

const meta = {
  kind: 'assessment_item',
  item_uid: item.item_uid,
  domain: item.domain,
  agent_id: item.agent_id,
  progress: ask.progress,
  asset: item.asset ? { asset_id: item.asset.asset_id } : null,
  asset_presented: !!assetUrl,
  word_list_presented: presentWords
};

return [{ json: {
  kind: 'assessment_item',
  draft_text: parts.join('\n\n'),
  meta: meta,
  attachment: assetUrl ? { asset_id: item.asset.asset_id, url: assetUrl } : null,
  state: state,
  config: upstream.config
} }];

// CERO 02 :: Session end. This is the only point at which a score exists anywhere
// outside the Documentation agent (plan section 4.3, score sequencing).
//
// STATE SOURCE MATTERS, same trap as Assessor: Compose Item. Assessor: Apply Score
// pushes the final item's result onto its own copy of the state. Reading
// $('Assessor: Resolve Turn') here fetches the state as it looked BEFORE that last
// answer was scored, so the last item in the sequence was silently dropped: it was
// asked, answered, and then thrown away when the session completed. That is why a
// full run reported 29 of 30 points attempted with the pentagon item missing from
// item_results entirely.
let upstream;
try {
  upstream = $('Assessor: Apply Score').first().json;
} catch (e) {
  upstream = $('Assessor: Resolve Turn').first().json;
}

const doc = $input.first().json.result;
const state = upstream.state;
const cfg = $('Config1').first().json;

state.mode = 'complete';
state.score_released = true;
state.clinical_note = doc.clinical_note_markdown;
state.final_scoring = doc.scoring;
state.assessor.awaiting = null;

const releaseToPatient = cfg.RELEASE_SCORE_TO_PATIENT === true || cfg.RELEASE_SCORE_TO_PATIENT === 'true';

let text = doc.patient_text;
if (releaseToPatient) {
  const s = doc.scoring;
  const band = (s.interpretation || []).map(b => b.interpretation).join('; ');
  text = text + '\n\n' + 'Your score today was ' + s.raw_score + ' out of ' + s.instrument_max + '.'
       + (band ? ' The instrument describes that range as: ' + band + '.' : '')
       + ' That is a number for a clinical professional to interpret, not a diagnosis, and it is only one piece of a much bigger picture.';
}

// Always skip tone on this turn. The Tone agent is told to strip anything score-shaped,
// which it does correctly on all other turns, and it has no way to know this is the
// one turn where the score is authorised. It was deleting the score line it had just
// been handed and reporting it in removed_leaks. This copy is deterministic and
// reviewed, so there is nothing for the Tone agent to add here anyway.
return [{ json: {
  kind: 'assessment_complete',
  draft_text: text,
  skip_tone: true,
  clinical_note_markdown: doc.clinical_note_markdown,
  scoring: doc.scoring,
  state: state,
  config: upstream.config
} }];

const res = $input.first().json.result;
const up = $('Educator: Build Payload').first().json;
return [{ json: { kind: 'education', draft_text: res.patient_text, meta: {
  routes: res.routes, used_entry_ids: res.used_entry_ids,
  ungrounded_entry_ids: res.ungrounded_entry_ids, weak_retrieval: res.weak_retrieval,
  out_of_scope: res.out_of_scope, disclaimer_required: res.disclaimer_required
}, state: up.state, config: up.config } }];

// CERO 02 :: Normalise every branch into one delivery envelope.
const j = $input.first().json;
const state = j.state;
const profile = state.profile || {};

const draft = j.draft_text || j.patient_text || '';

return [{ json: {
  kind: j.kind,
  draft_text: draft,
  skip_tone: !!j.skip_tone,
  meta: j.meta || null,
  attachment: j.attachment || null,
  clinical_note_markdown: j.clinical_note_markdown || null,
  scoring: j.scoring || null,
  safety: j.safety || null,
  human_review_required: !!j.human_review_required,
  state: state,
  config: j.config,
  tone_payload: JSON.stringify({
    draft_text: draft,
    profile: {
      role: profile.role, education_level: profile.education_level,
      preferred_name: profile.preferred_name, accessibility_needs: profile.accessibility_needs || []
    },
    config: j.config
  })
} }];

// CERO 02 :: Final output guard. Runs on every patient-facing string regardless of
// which branch produced it. Deterministic, so a violation is reproducible in review.
const tone = $input.first().json.result;
const env = $('Turn: Prepare Delivery').first().json;
const state = env.state;
const cfg = $('Config1').first().json;

let text = env.skip_tone ? env.draft_text.replace(/<<\/?VERBATIM>>/g, '') : (tone && tone.text ? tone.text : env.draft_text.replace(/<<\/?VERBATIM>>/g, ''));
const toneApplied = !!(tone && tone.rewrite_applied) && !env.skip_tone;
const violations = [];

const sessionComplete = state.mode === 'complete';

// 1. Score sequencing. Nothing score-shaped leaves before the session is complete.
//    After completion the Documentation agent is the authority, so these are allowed.
const scoreShaped = [
  // slash form is restricted to real instrument maxima: an unrestricted \d/\d also
  // matches ordinary copy such as "24/7", which suppressed the crisis message in test
  /\b\d{1,3}\s*\/\s*(?:30|100)\b/,
  /\b\d{1,3}\s+out of\s+\d{1,3}\b/i,
  /\b(?:your|the|running|total)\s+(?:score|total|result|tally)\b/i,
  /\b\d+\s*points?\b/i,
  /\bso far you(?:'ve| have)\b/i
];
if (!sessionComplete) {
  for (const re of scoreShaped) {
    if (re.test(text)) { violations.push('score_leak'); break; }
  }
}

// 2. Interpretation bands. Same rule: only the end-of-session release may carry them.
const bandTerms = /\b(?:mild|moderate|severe) cognitive impairment\b|\bnormal cognition\b|\b(?:in|de)creased odds of dementia\b/i;
if (!sessionComplete && bandTerms.test(text)) violations.push('band_leak');

// 3. Diagnosis. Always blocked, in every mode.
//    Matched on assertions only. A bare mention of the word "diagnosis" is legitimate
//    and appears in our own consent copy ("nothing here is a diagnosis"), so matching
//    the word itself produces false positives on reviewed disclaimer text.
const diagnostic = [
  /\b(?:you|she|he|they)\s+(?:have|has|are showing|is showing|are developing|is developing|likely have|probably have|may have|might have)\b[^.]{0,60}\b(?:alzheimer|dementia|impairment|decline|mci|condition|disease)\b/i,
  /\b(?:i|this|that|these results?|your (?:answers?|responses?|score))\s+(?:would |can |could |will )?(?:diagnos\w+|indicat\w+ that you|suggest\w* that you|mean\w* that you)\b/i,
  /\bi (?:can|could|am able to) (?:diagnose|tell you (?:whether|if) you)\b/i,
  /\byour (?:prognosis|diagnosis) (?:is|would be)\b/i
];
for (const re of diagnostic) {
  if (re.test(text)) { violations.push('diagnostic_language'); break; }
}

// 4. No evaluative feedback during the assessment. Matched on phrases, not single
//    words: "correct" and "close" both occur inside legitimate MMSE item wording
//    (for example "Close your eyes"), so word-level matching is unusable here.
if (state.mode === 'assessor') {
  const evaluative = [
    /\bthat(?:'s| is| was)\s+(?:right|correct|wrong|incorrect|close|not quite)\b/i,
    /\b(?:well done|good job|nice work|great job|perfect|exactly right|you got (?:it|that) right)\b/i,
    /\b(?:correct|incorrect|wrong) answer\b/i,
    /\byou (?:answered|got) (?:that|it) (?:correctly|incorrectly|wrong)\b/i
  ];
  for (const re of evaluative) {
    if (re.test(text)) { violations.push('evaluative_feedback'); break; }
  }
}

// 5. PII echo. Flags only details the patient themselves volunteered, which is what
//    the rule actually is. A blanket pattern match would flag our own crisis-line
//    numbers, which must never be suppressed.
const patientSaid = (state.transcript || []).filter(t => t.role === 'patient')
  .map(t => String(t.text || '')).join(' \n ');
const piiPatterns = [
  [/\b\d{3}-\d{2}-\d{4}\b/g, 'ssn_shaped'],
  [/\b\d{1,5}\s+[A-Za-z]+\s+(?:street|st|road|rd|avenue|ave|lane|ln|drive|dr|boulevard|blvd)\b/gi, 'street_address'],
  [/\b[\w.\-]+@[\w\-]+\.\w{2,}\b/g, 'email'],
  [/\b(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}\b/g, 'phone'],
  [/\b\d{1,2}\/\d{1,2}\/(?:19|20)\d{2}\b/g, 'date_shaped']
];
const echoed = [];
const norm = (s) => s.replace(/[^0-9a-z@.]/gi, '').toLowerCase();
for (const [re, label] of piiPatterns) {
  const hits = text.match(re) || [];
  for (const h of hits) {
    if (norm(patientSaid).indexOf(norm(h)) !== -1 && echoed.indexOf(label) === -1) echoed.push(label);
  }
}
if (echoed.length) violations.push('pii_echo:' + echoed.join(','));

// A crisis turn is reviewed, clinician-signed copy. Suppressing it because a regex
// fired is strictly more dangerous than emitting it, so it is never replaced. The
// violation is still recorded so a template regression is caught in review.
let blocked = false;
if (violations.length && env.kind === 'crisis') {
  violations.push('crisis_template_not_suppressed');
} else if (violations.length) {
  blocked = true;
  const raw = env.draft_text.replace(/<<\/?VERBATIM>>/g, '').trim();
  if (env.kind === 'assessment_item' && env.meta) {
    text = 'Here is the next question.\n\n' + raw.split('\n\n').pop();
  } else if (env.kind === 'intake' || env.kind === 'intake_complete') {
    // authored template text: re-emit it directly rather than dropping the step
    text = raw;
  } else {
    text = 'Let me put that a different way. Could you tell me a little more about what you would like to know?';
  }
}

state.transcript.push({ role: 'assistant', text: text, at: Date.now(), kind: env.kind });
if (state.transcript.length > 40) state.transcript = state.transcript.slice(-40);

return [{ json: {
  kind: env.kind,
  text: text,
  attachment: env.attachment,
  meta: env.meta,
  guard: {
    violations: violations,
    blocked: blocked,
    tone_applied: toneApplied,
    tone_fallback_reason: tone ? tone.fallback_reason : null,
    // Only report removals that actually survived into `text`. The tone agent still
    // self-reports removed_leaks on turns where its rewrite was discarded, which made
    // the clinician payload claim edits the patient never saw.
    removed_leaks: toneApplied ? (tone.removed_leaks || []) : []
  },
  clinical_note_markdown: env.clinical_note_markdown,
  scoring: env.scoring,
  safety: env.safety,
  human_review_required: env.human_review_required,
  state: state
} }];

// CERO 02 :: Persist and shape the API response.
const j = $input.first().json;
const store = $getWorkflowStaticData('global');
const state = j.state;
const cfg = $('Config1').first().json;

state.updated_at = Date.now();
store.sessions[state.session_id] = state;

const a = state.assessor || {};
const response = {
  session_id: state.session_id,
  mode: state.mode,
  kind: j.kind,
  reply: j.text,
  attachment: j.attachment || null,
  progress: j.meta && j.meta.progress ? j.meta.progress : null,
  human_review_required: !!j.human_review_required,
  turn: state.turn_count
};

// The clinician payload never rides on the patient response.
const clinician = {
  session_id: state.session_id,
  corpus_version: cfg.CORPUS_VERSION_EXPECTED || null,
  scoring: j.scoring || null,
  clinical_note_markdown: j.clinical_note_markdown || null,
  safety_events: state.safety_events,
  guard: j.guard,
  item_results: a.item_results || [],
  not_administered: a.skipped_items || [],
  instrument_selection_reason: a.instrument_selection_reason || null
};

return [{ json: {
  response: response,
  clinician: clinician,
  eval_record: {
    at: new Date().toISOString(),
    session_id: state.session_id,
    turn: state.turn_count,
    mode: state.mode,
    kind: j.kind,
    guard_violations: j.guard.violations,
    tone_applied: j.guard.tone_applied,
    safety: j.safety || null,
    item_uid: j.meta ? j.meta.item_uid : null,
    agent_id: j.meta ? j.meta.agent_id : null
  }
} }];

// CERO :: Normalise the two entry points into one shape.
//
// Chat Trigger gives { chatInput, sessionId }. The webhook gives { body: {...} }.
// Everything downstream reads this node explicitly, so neither trigger's payload can
// be stripped by a Set node in between.
//
// Extract: Chat Upload sits in front of this node to materialise uploaded bytes. On a
// text-only turn it has no binary to extract, and with onError continueRegularOutput it
// emits { error: "...expects binary..." } which REPLACES the trigger payload rather than
// passing it through. That wiped sessionId and made every ordinary turn fail. So the
// trigger payload is recovered by node reference whenever the incoming item does not
// look like a real trigger payload.
function pickSource() {
  const inp = $input.first();
  const j = (inp && inp.json) || {};
  const usable = j.chatInput !== undefined || j.sessionId !== undefined
    || j.body !== undefined || j.session_id !== undefined;
  if (usable) return inp;

  for (const name of ['Chat Trigger', 'Webhook: Turn']) {
    try {
      const t = $(name).first();
      const tj = (t && t.json) || {};
      if (tj.chatInput !== undefined || tj.sessionId !== undefined || tj.body !== undefined) return t;
    } catch (e) { /* that trigger did not fire on this run */ }
  }
  return inp;
}

const src = pickSource();
const raw = src.json || {};
const body = raw.body || raw;

const isChat = raw.chatInput !== undefined || raw.sessionId !== undefined;

const sessionId = String(
  (isChat ? raw.sessionId : body.session_id) || body.session_id || ''
).trim();

const message = String(
  (isChat ? raw.chatInput : body.message) || body.message || ''
);

if (!sessionId) {
  throw new Error('session_id is required. The chat widget supplies one automatically; ' +
    'raw webhook callers must send {"session_id": "...", "message": "..."}.');
}

// Patient-supplied attachment, e.g. a photo of a drawn figure or of a completed motor
// task. The base64 lives on the Extract node's own output, which is $input, not on the
// recovered trigger item. Carried as a data URI so it survives the Execute Workflow
// boundary into the scoring island, which JSON-serialises and would drop binary.
const extracted = $input.first();
const exJson = (extracted && extracted.json) || {};
const binKeys = extracted && extracted.binary ? Object.keys(extracted.binary) : [];
const bin = binKeys.length ? extracted.binary[binKeys[0]] : null;
const b64 = typeof exJson.upload_b64 === 'string' ? exJson.upload_b64 : null;

let attachment = null;
if (b64 && b64.length && b64 !== 'filesystem-v2') {
  const mime = (bin && bin.mimeType) || 'application/octet-stream';
  attachment = {
    mime_type: mime,
    file_name: (bin && bin.fileName) || null,
    is_image: /^image\//.test(mime),
    data_uri: 'data:' + mime + ';base64,' + b64,
    bytes: b64.length
  };
}

// Raw webhook callers can post a data URI directly rather than multipart.
if (!attachment && typeof body.attachment_data_uri === 'string' && body.attachment_data_uri.startsWith('data:')) {
  const m = /^data:([^;]+);base64,/.exec(body.attachment_data_uri);
  attachment = {
    mime_type: m ? m[1] : 'application/octet-stream',
    file_name: body.attachment_file_name || null,
    is_image: m ? /^image\//.test(m[1]) : false,
    data_uri: body.attachment_data_uri,
    bytes: body.attachment_data_uri.length
  };
}

return [{ json: {
  session_id: sessionId,
  message: message,
  mode: String(body.mode || '').trim(),
  is_chat: isChat,
  attachment: attachment,
  has_attachment: !!attachment
} }];

// CERO :: Single terminal for both entry points.
//
// The chat widget (responseMode: lastNode) renders the `output` field. Raw webhook
// callers get the same object, so one node serves both.
//
// Chain is deliberately linear: Session: Save -> Log: Eval Sink -> Reply. Reply must
// be the ONLY terminal, because lastNode response mode returns whichever node finishes
// last. When this sat as a sibling branch of the eval sink, the disabled sink won the
// race and passed Session: Save's full envelope to the widget instead of this shape.
//
// Reads Session: Save by reference rather than $input, so this node is immune to what
// the eval sink emits once it is enabled and stops being a passthrough.
//
// The clinician payload is deliberately NOT included: scores, the clinical note and
// safety events leave via Log: Eval Sink only, never on the patient-facing reply.
const j = $('Session: Save').first().json;
const r = j.response;

return [{ json: {
  output: r.reply,
  session_id: r.session_id,
  mode: r.mode,
  kind: r.kind,
  progress: r.progress,
  attachment: r.attachment,
  human_review_required: r.human_review_required,
  turn: r.turn
} }];

// Adapt the OpenAI Responses node output into the tool_use shape the downstream Parse
// node expects, so that node stays byte-identical to the tested version.
//
// Shape returned by the OpenAI node with simplify:true and textFormat json_object:
//   { output: [ { content: [ { type: 'output_text', text: {...} } ] } ] }
// Note `text` is ALREADY a parsed object, not a string, because JSON output mode is on.
// An earlier version called String() on it and got "[object Object]".
const res = $input.first().json;

function findPayload(r) {
  if (r == null) return null;
  if (Array.isArray(r.output)) {
    for (const msg of r.output) {
      for (const c of (msg && msg.content) || []) {
        if (c && c.text !== undefined) return c.text;
      }
    }
  }
  if (r.output_text !== undefined) return r.output_text;
  if (typeof r.content === 'string') return r.content;
  if (Array.isArray(r.content)) {
    for (const c of r.content) if (c && c.text !== undefined) return c.text;
  }
  if (r.text !== undefined) return r.text;
  if (r.message && Array.isArray(r.message.content)) {
    for (const c of r.message.content) if (c && c.text !== undefined) return c.text;
  }
  return null;
}

function coerce(v) {
  if (v && typeof v === 'object') return v;
  const t = String(v == null ? '' : v).trim()
    .replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
}

if (res && res.error) return [{ json: { error: res.error } }];

const parsed = coerce(findPayload(res));
if (!parsed) {
  // Surface the actual model response so a shape change is debuggable at a glance.
  return [{ json: { error: { type: 'parse_error',
    message: 'Could not extract a JSON object from the model response.',
    raw_response: JSON.stringify(res).slice(0, 1500) } } }];
}

return [{ json: { content: [{ type: 'tool_use', input: parsed }] } }];

