parameters.jsCode:
// Parse the durable corpus row and cache it in-process for the rest of this execution.
const row = $input.first().json;

if (!row || !row.payload) {
  throw new Error(
    'No corpus found in the cero_corpus data table. Run the data loader island once: ' +
    'pick the two files in the Drive nodes, then execute the Manual Trigger.'
  );
}

let artifact;
try {
  artifact = JSON.parse(row.payload);
} catch (e) {
  throw new Error('Corpus row in cero_corpus is not valid JSON: ' + e.message);
}
if (!artifact || !Array.isArray(artifact.item_bank)) {
  throw new Error('Corpus row in cero_corpus is malformed: expected item_bank[].');
}

const store = $getWorkflowStaticData('global');
store.corpus = artifact;
store.corpus_fetched_at = Date.now();

const req = $('Corpus: Check Cache').first().json;
return [{ json: { agent_id: req.agent_id, payload: req.payload, cache_hit: false, corpus_version: artifact.corpus_version } }];

// Merge the agent's structured profile into session state, then select the instrument.
const out = $input.first().json.output || $input.first().json;
const up = $('Route: Track').first().json;
const state = up.state;
const cfg = $('Config1').first().json;
const msg = String(up.message || '').trim();

const p = out.profile || {};

// Treat empty string as "not provided". The structured output parser forces every schema
// field to be present, so the agent emits "" for fields it has not asked about yet.
const provided = (v) => v !== undefined && v !== null && v !== '';

for (const k of ['role','preferred_name','age_band','sex','education_level','presenting_concerns']) {
  if (provided(p[k])) state.profile[k] = p[k];
}
if (Array.isArray(p.accessibility_needs)) state.profile.accessibility_needs = p.accessibility_needs;
if (p.consent === true) state.profile.consent = true;

const EDU_YEARS = { less_than_high_school: 10, high_school: 12, some_college: 14, college_plus: 16 };
if (state.profile.education_level) state.profile.education_years = EDU_YEARS[state.profile.education_level] || null;

// A refusal must come from the PERSON, not from the model. The parser makes the agent
// emit `declined` on every turn, including the opening one.
const saidNo = /\b(no|nope|nah|not now|stop|quit|cancel|later|don'?t want|do not want|i refuse|rather not)\b/i.test(msg);

if (p.declined === true && saidNo) {
  state.mode = 'declined';
  return [{ json: { kind: 'intake', skip_tone: true, state: state, config: up.config,
    draft_text: out.reply || 'That is completely fine, and thank you for telling me. Nothing has been recorded. If you change your mind later, we can pick this up any time.' } }];
}

if (!out.complete || state.profile.consent !== true) {
  return [{ json: { kind: 'intake', skip_tone: true, state: state, config: up.config,
    draft_text: out.reply || 'Could you tell me a little more?' } }];
}

// ---- Instrument selection -------------------------------------------------
//
// Presenting symptoms are the primary factor; education is a tiebreak only.
// Education deliberately never pushes AWAY from the MoCA on its own: the MoCA carries
// its own adjustment (+1 for 12 years of schooling or less), so low educational
// attainment is not in itself a reason to avoid it. The question is whether the
// symptoms suggest something the MMSE's simpler battery might miss.
function selectInstrument(profile) {
  const text = [].concat(profile.presenting_concerns || []).join(' ').toLowerCase();
  const eduYears = Number(profile.education_years);

  // Domains the MoCA probes more deeply: attention, working memory, executive
  // function, abstraction, uncued delayed recall.
  const mocaSignals = /attention|concentrat|focus|distract|working memory|multitask|juggl|executive|planning|organis|organiz|decision|judg[e]?ment|word.?finding|find the right word|fatigue|foggy|brain fog|subtle|mild|early|slight|keeping up|bills|budget|finances|driving|directions|recipe|sequenc/;

  // Presentation consistent with more advanced decline, where the MMSE is sufficient
  // and quicker to administer.
  const mmseSignals = /confus|disorient|got lost|wander|forget(ting)? (my |the )?(family|name|face)|repeat(ing)? (the same|question)|not recognis|not recognize|severe|advanced|late stage|nursing|bedbound|help with (dressing|bathing|eating|toilet)/;

  const moca = mocaSignals.test(text);
  const mmse = mmseSignals.test(text);

  if (moca && !mmse) return { id: 'moca',
    reason: 'Presenting complaint is early, subtle, or executive/attention-based, a profile more consistent with MCI. The MoCA probes serial subtraction, trail-making, abstraction and uncued delayed recall, which the MMSE does not test as deeply.' };
  if (mmse && !moca) return { id: 'mmse',
    reason: 'Presenting complaint reads as memory loss with confusion, consistent with more advanced decline. The MMSE is sufficient and quicker to administer.' };
  if (moca && mmse) return { id: 'mmse',
    reason: 'Mixed presentation with both subtle and advanced features. MMSE selected as the simpler, quicker screen; a MoCA follow-up may be worth considering.' };
  if (Number.isFinite(eduYears) && eduYears <= 10) return { id: 'mmse',
    reason: 'No clear symptom signal either way. Lower educational attainment, so the MMSE was chosen for its simpler battery and its education-adjusted cutoffs.' };
  return { id: cfg.DEFAULT_INSTRUMENT || 'mmse',
    reason: 'No clear symptom signal either way; configured default used.' };
}

const rec = selectInstrument(state.profile);
state.assessor.instrument_recommended = rec.id;
state.assessor.instrument_recommendation_reason = rec.reason;

// The recommendation is always recorded, even when it cannot be honoured, so the
// research data shows what the rule chose rather than only what was administered.
const mocaEnabled = cfg.ENABLE_MOCA === true || cfg.ENABLE_MOCA === 'true';
let chosen = rec.id;
let reason = rec.reason;

if (rec.id === 'moca' && !mocaEnabled) {
  chosen = 'mmse';
  reason = rec.reason + ' SUBSTITUTED: the MoCA was indicated but is not enabled on this channel, because 15 of its 30 points require drawing, timed, or observed-motor responses that a text session cannot administer. The MMSE was given instead.';
  state.assessor.instrument_substituted = true;
}

state.assessor.instrument_id = chosen;
state.assessor.instrument_selection_reason = reason;
state.assessor.started_at = Date.now();
state.mode = 'assessor';

return [{ json: { kind: 'intake_complete', skip_tone: true, state: state, config: up.config,
  draft_text: (out.reply ? out.reply + '\n\n' : '') +
    'That is everything I needed. We can start whenever you are ready. There is no time limit, and it is completely fine to say you do not know.' } }];

// CERO 01 :: Turn the Drive asset folder into inline data URIs.
//
// There is no static web host in this deployment, and a Drive folder link is a viewer
// page rather than a file path, so ASSET_BASE + '/' + asset_id + '.png' can never
// resolve. Reading the bytes through the Drive credential and inlining them as data
// URIs removes the hosting dependency completely and works with a private folder.
//
// This instance runs binaryMode 'separate', so item.binary.data.data is a filesystem
// pointer ('filesystem-v2'), not base64. Extract From File in binaryToPropery mode is
// what actually materialises the bytes, into json.b64.
//
// asset_id is the filename without extension, so mmse_pentagons.png -> mmse_pentagons,
// which is exactly what assetId() in the normalizer produces.
const assets = {};
const skipped = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const binKeys = item.binary ? Object.keys(item.binary) : [];
  const bin = binKeys.length ? (item.binary.data || item.binary[binKeys[0]]) : null;

  const name = j.name || j.fileName || (bin && bin.fileName) || '';
  const b64 = j.b64;
  const mime = (bin && bin.mimeType) || j.mimeType || 'image/png';

  if (!name) { skipped.push('(unnamed file)'); continue; }
  if (typeof b64 !== 'string' || !b64.length || b64 === 'filesystem-v2') {
    skipped.push(String(name) + ' (no base64 payload)');
    continue;
  }
  if (!/^image\//.test(mime)) { skipped.push(String(name) + ' (not an image: ' + mime + ')'); continue; }

  const assetId = String(name).replace(/\.[^.]+$/, '');
  assets[assetId] = 'data:' + mime + ';base64,' + b64;
}

return [{ json: {
  assets: assets,
  asset_ids: Object.keys(assets),
  asset_count: Object.keys(assets).length,
  asset_bytes: Object.values(assets).reduce((a, b) => a + b.length, 0),
  skipped: skipped
} }];

